  {t="T", q=1515, name="Dogran's Captivity", z=17, x=43.3, y=47.89, target={kind="npc", id=5908, name="Grunt Dogran"}, tip="Dogran is chained up in the quilboar camp west of the road.", classes={"Warlock"}, section="The Barrens (14-23)", zoneName="The Barrens", p=692, place="Grunt Dogran", was=1974}, -- 2037
  {t="A", q=1512, name="Love's Gift", z=17, x=43.3, y=47.89, target={kind="npc", id=5908, name="Grunt Dogran"}, note="Keep it: Gan'rul in Orgrimmar, on the next guide's Orgrimmar stop", classes={"Warlock"}, section="The Barrens (14-23)", zoneName="The Barrens", p=692, place="Grunt Dogran", was=1975}, -- 2038
  {t="C", q=907, obj=1, name="Enraged Thunder Lizards", gv="Collect", gw="Thunder Lizard Blood", z=17, x=42.89, y=46.9, note="Collect Thunder Lizard Blood", tip="Thunderheads graze on the plains just south of Camp Taurajo. Owatanka, a blue thunder lizard (level 24), roams among them: his Tailspike starts a quest. Leave him alone below level 23.", section="The Barrens (14-23)", zoneName="The Barrens", p=693, place="Enraged Thunder Lizards", was=1976}, -- 2039
  {t="N", text="Collect Owatanka's Tailspike", optional=true, note="Owatanka's Tailspike", section="The Barrens (14-23)", p=693, place="Enraged Thunder Lizards"}, -- 2040
  {t="A", q=884, name="Owatanka", optional=true, z=17, x=42.89, y=46.9, target={kind="item", id=5102, name="Owatanka's Tailspike"}, section="The Barrens (14-23)", zoneName="The Barrens", p=693, place="Enraged Thunder Lizards", was=1978}, -- 2041
  {t="T", q=907, name="Enraged Thunder Lizards", z=17, x=44.86, y=59.14, target={kind="npc", id=3387, name="Jorn Skyseer"}, tip="Warriors: take Trial at the Field of Giants from Ruga Ragetotem now: it runs for 30 minutes from the accept. The antennae come first, at the Silithid Mounds south of the camp, then straight back to Ruga; the thunderhawks after.", section="The Barrens (14-23)", zoneName="The Barrens", p=694, place="Jorn Skyseer", was=1979}, -- 2042
  {t="A", q=913, name="Cry of the Thunderhawk", z=17, x=44.86, y=59.14, target={kind="npc", id=3387, name="Jorn Skyseer"}, section="The Barrens (14-23)", zoneName="The Barrens", p=694, place="Jorn Skyseer", was=1980}, -- 2043
  {t="T", q=884, name="Owatanka", optional=true, z=17, x=44.86, y=59.14, target={kind="npc", id=3387, name="Jorn Skyseer"}, section="The Barrens (14-23)", zoneName="The Barrens", p=694, place="Jorn Skyseer", was=1981}, -- 2044
  {t="A", q=1824, name="Trial at the Field of Giants", z=17, x=44.67, y=59.42, target={kind="npc", id=6394, name="Ruga Ragetotem"}, note="Ruga Ragetotem, inside", classes={"Warrior"}, section="The Barrens (14-23)", zoneName="The Barrens", p=694, place="Jorn Skyseer", was=1982}, -- 2045
  {t="C", q=1824, obj=1, name="Trial at the Field of Giants", z=17, x=45.11, y=68.95, note="Twitching Antennae from the silithid", tip="The antennae vanish fifteen minutes after they drop: kill the Silithid Swarmers and Creepers at the Silithid Mounds in the Field of Giants, south of Camp Taurajo, until you have five, then take them straight to Ruga Ragetotem in Camp Taurajo, before the thunderhawks. Careful: Silithid Swarmers (level 21-22) cast Silithid Swarm both in and out of combat, which brings several small adds; Silithid Creepers (level 20-21) periodically cast Silithid Creeper Egg in combat, which spawns extra adds. A Silithid Harvester (24, rare) also wanders the mounds: leave it.", classes={"Warrior"}, section="The Barrens (14-23)", zoneName="The Barrens", p=695, place="Twitching Antennae", was=1983}, -- 2046
  {t="T", q=1824, name="Trial at the Field of Giants", z=17, x=44.67, y=59.42, target={kind="npc", id=6394, name="Ruga Ragetotem"}, note="Ruga Ragetotem, inside", tip="Back north into Camp Taurajo before the antennae fade: Ruga Ragetotem is inside.", classes={"Warrior"}, section="The Barrens (14-23)", zoneName="The Barrens", p=696, place="Ruga Ragetotem", was=1984}, -- 2047
  {t="A", q=1825, name="Speak with Thun'grim", z=17, x=44.67, y=59.42, target={kind="npc", id=6394, name="Ruga Ragetotem"}, classes={"Warrior"}, section="The Barrens (14-23)", zoneName="The Barrens", p=696, place="Ruga Ragetotem", was=1985}, -- 2048
  {t="C", q=913, obj=1, name="Cry of the Thunderhawk", gv="Collect", gw="Thunderhawk Wings", z=17, x=46.69, y=61.49, note="Collect Thunderhawk Wings", tip="Thunderhawk Cloudscrapers circle over the plains south of the camp.", section="The Barrens (14-23)", zoneName="The Barrens", p=697, place="Cry of the Thunderhawk", was=1986}, -- 2049
  {t="T", q=1530, name="Call of Water", z=17, x=43.42, y=77.41, target={kind="npc", id=5899, name="Brine"}, note="Brine", tip="Brine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo: fill the Empty Brown Waterskin at the watering hole below it.", classes={"Shaman"}, section="The Barrens (14-23)", zoneName="The Barrens", p=698, place="Brine", was=1987}, -- 2050
  {t="A", q=1535, name="Call of Water", z=17, x=43.42, y=77.41, target={kind="npc", id=5899, name="Brine"}, classes={"Shaman"}, section="The Barrens (14-23)", zoneName="The Barrens", p=698, place="Brine", was=1988}, -- 2051
