  {t="T", q=913, name="Cry of the Thunderhawk", z=17, x=44.86, y=59.14, target={kind="npc", id=3387, name="Jorn Skyseer"}, note="Jorn Skyseer", tip="Back north into Camp Taurajo on the way to the Crossroads: Jorn takes the thunderhawk wings.", section="The Barrens (14-23)", zoneName="The Barrens", p=699, place="Camp Taurajo", was=1992}, -- 2055
  {t="T", q=880, name="Altered Beings", z=17, x=52.26, y=31.93, target={kind="npc", id=3448, name="Tonga Runetotem"}, note="Tonga Runetotem", tip="North up the Gold Road to the Crossroads: Tonga Runetotem at the south gate, Mankrik by the inn, Korran west of the north gate.", section="The Barrens (14-23)", zoneName="The Barrens", p=700, place="The Crossroads", was=1993}, -- 2056
  {t="T", q=95774, name="Her Name Is Olgra", foreverOnly=true, z=17, x=51.95, y=31.58, target={kind="npc", id=3432, name="Mankrik"}, note="Mankrik", section="The Barrens (14-23)", zoneName="The Barrens", p=700, place="The Crossroads", was=1994}, -- 2057
  {t="A", q=868, name="Egg Hunt", z=17, x=51.07, y=29.63, target={kind="npc", id=3428, name="Korran"}, note="Korran, west of the north gate: keep Egg Hunt, its eggs lie on the next Barrens guide's walk south from Camp Taurajo, at about 25", section="The Barrens (14-23)", zoneName="The Barrens", p=700, place="The Crossroads", was=1995}, -- 2058
  {t="T", q=1825, name="Speak with Thun'grim", z=17, x=57.23, y=30.34, target={kind="npc", id=5878, name="Thun'grim Firegaze"}, note="Thun'grim Firegaze", tip="Thun'grim camps beside the road east of the Crossroads.", classes={"Warrior"}, section="The Barrens (14-23)", zoneName="The Barrens", p=701, place="Thun'grim Firegaze", was=1996}, -- 2059
  {t="N", text="He offers Brutal Armor next (1838, level 30): it needs Razorfen Kraul and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide Brutal Armor covers it.", classes={"Warrior"}, section="The Barrens (14-23)", p=701, place="Thun'grim Firegaze"}, -- 2060
