  {t="C", q=4021, obj=1, name="Counterattack!", z=17, x=44.4, y=28.1, note="Piece of Krom'zar's Banner", tip="Speak to Regthar again to start the attack: the Kolkar charge the bunkers just west of him in waves. Fight beside the grunts until Warlord Krom'zar (elite, 20) arrives with two bodyguards, usually from the south, then click the banner over his body.", section="The Barrens (14-23)", zoneName="The Barrens", p=703, place="Counterattack!", was=2000}, -- 2063
  {t="T", q=4021, name="Counterattack!", z=17, x=45.34, y=28.41, target={kind="npc", id=3389, name="Regthar Deathgate"}, note="Regthar Deathgate", section="The Barrens (14-23)", zoneName="The Barrens", p=703, place="Counterattack!", was=2001}, -- 2064
