  {t="A", q=1062, name="Goblin Invaders", z=17, x=35.26, y=27.88, target={kind="npc", id=4049, name="Seereth Stonebreak"}, note="Seereth Stonebreak: the Venture loggers at Windshear Crag", section="The Barrens (14-23)", zoneName="The Barrens", p=705, place="Seereth Stonebreak", was=2004}, -- 2067
