  {t="T", q=1060, name="Letter to Jin'Zil", z=406, x=74.54, y=97.94, target={kind="npc", id=3995, name="Witch Doctor Jin'Zil"}, tip="Follow the road on west from Seereth into Stonetalon. The troll village of Malaka'jin sits at the entrance of the canyon.", classes={"!Warlock"}, section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=709, place="Malaka'jin", was=2011}, -- 2074
  {t="A", q=6461, name="Blood Feeders", z=406, x=71.25, y=95.02, target={kind="npc", id=12816, name="Xen'Zilla"}, note="Xen'Zilla: the spiders along the Webwinder Path", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=709, place="Malaka'jin", was=2012}, -- 2075
  {t="C", q=6629, obj=1, name="Kill Grundig Darkcloud", gv="Kill", gw="Grundig Darkcloud", z=406, x=73.65, y=86.12, note="Kill Grundig Darkcloud", tip="North up the road from Malaka'jin: Grundig Darkcloud and his Grimtotem Brutes hold the bend in the road, and the Deepmoss Creepers and Venomspitters lurk in the webs on both sides of the path all the way up.", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=710, place="Webwinder Path: kill these as you meet them", was=2013}, -- 2076
  {t="C", q=6629, obj=2, name="Kill Grundig Darkcloud", gv="Kill", gw="Grimtotem Brute", z=406, x=73.84, y=85.8, note="Kill Grimtotem Brute", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=710, place="Webwinder Path: kill these as you meet them", was=2014}, -- 2077
