  {t="A", q=1093, name="Super Reaper 6000", z=406, x=58.99, y=62.6, target={kind="npc", id=4201, name="Ziz Fizziks"}, section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=711, place="Ziz Fizziks", was=2018}, -- 2081
  {t="C", q=1093, name="Super Reaper 6000", gv="Collect", gw="Super Reaper 6000 Blueprints", z=406, x=62.51, y=53.84, note="Collect Super Reaper 6000 Blueprints", tip="East of Ziz, the Venture Company is clear-cutting Windshear Crag; one of the Operators carries the blueprints.", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=712, place="Windshear Crag", was=2019}, -- 2082
  {t="C", q=1062, obj=1, name="Goblin Invaders", z=406, x=63.61, y=54.36, note="Venture Co. Loggers, all over the clear-cut", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=712, place="Windshear Crag", was=2020}, -- 2083
  {t="A", q=1090, name="Gerenzo's Orders", group=true, z=406, x=71.87, y=60, target={kind="npc", id=4276, name="Piznik"}, note="Piznik, below ground", tip="Piznik mines at the bottom of the Windshear Mine on the east side of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails.", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=713, place="Piznik", was=2021}, -- 2084
  {t="C", q=1090, name="Gerenzo's Orders", group=true, z=406, x=71.87, y=60, section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=713, place="Piznik", was=2022}, -- 2085
