  {t="T", q=1092, name="Gerenzo's Orders", group=true, z=406, x=58.99, y=62.6, target={kind="npc", id=4201, name="Ziz Fizziks"}, note="Ziz Fizziks, inside", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=714, place="Ziz Fizziks: Gerenzo's Orders", was=2025}, -- 2088
  {t="T", q=1093, name="Super Reaper 6000", z=406, x=58.99, y=62.6, target={kind="npc", id=4201, name="Ziz Fizziks"}, note="Ziz Fizziks, inside", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=715, place="Ziz Fizziks", was=2026}, -- 2089
