  {t="A", q=6523, name="Protect Kaya", z=406, x=73.5, y=85.6, target={kind="npc", id=11856, name="Kaya Flathoof"}, note="Kaya Flathoof, inside Grundig's hut", tip="Careful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly.", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=716, place="Kaya Flathoof", was=2028}, -- 2091
  {t="C", q=6523, name="Protect Kaya", z=406, x=77.1, y=90.8, section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=716, place="Kaya Flathoof", was=2029}, -- 2092
  {t="T", q=6461, name="Blood Feeders", z=406, x=71.25, y=95.02, target={kind="npc", id=12816, name="Xen'Zilla"}, note="Xen'Zilla", tip="West from the burned village to Malaka'jin: Xen'Zilla stands just outside it, before the village.", section="The Barrens (14-23)", zoneName="Stonetalon Mountains", p=717, place="Malaka'jin", was=2030}, -- 2093
