  {t="A", q=1063, name="The Elder Crone", z=17, x=35.26, y=27.88, target={kind="npc", id=4049, name="Seereth Stonebreak"}, note="Seereth Stonebreak: The Elder Crone, Magatha in Thunder Bluff, on the next guide's way back from Zoram'gar", section="The Barrens (14-23)", zoneName="The Barrens", p=719, place="Seereth Stonebreak", was=2033}, -- 2096
