  {t="TR", text="Train at your class trainer", classes={"Warrior", "Hunter", "Rogue", "Priest", "Shaman", "Mage", "Warlock"}, section="Ashenvale & Silverpine Forest (22-23)", p=739, place="Orgrimmar"}, -- 2144
  {t="T", q=1512, name="Love's Gift", z=1637, x=48.25, y=45.28, target={kind="npc", id=5875, name="Gan'rul Bloodeye"}, tip="Gan'rul Bloodeye stands in the Cleft of Shadow. Use Dogran's Pendant on the summoning circle there and defeat the succubus to bind her.", classes={"Warlock"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=740, place="The Binding", was=2082}, -- 2145
  {t="A", q=1513, name="The Binding", z=1637, x=48.25, y=45.28, target={kind="npc", id=5875, name="Gan'rul Bloodeye"}, classes={"Warlock"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=740, place="The Binding", was=2083}, -- 2146
  {t="N", text="Use Dogran's Pendant", z=1637, x=49.4, y=50.0, note="Dogran's Pendant", classes={"Warlock"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=740, place="The Binding"}, -- 2147
