  {t="C", q=496, obj=1, name="Elixir of Suffering", gv="Collect", gw="Gray Bear Tongue", z=267, x=54.3, y=39.6, note="Collect Gray Bear Tongue", tip="West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop Creeper Ichor rarely; you need only one.", section="Hillsbrad Foothills (23-25)", zoneName="Hillsbrad Foothills", p=755, place="Bears, creepers and lions", was=2131}, -- 2194
