  {t="C", q=527, obj=1, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Farmer", z=267, x=36.38, y=39.77, note="Kill Hillsbrad Farmer", tip="The farms east of Hillsbrad town. Farmer Ray works the field by the northern farmhouse, Farmer Getz the one further south-east; Farmhands and Farmers are everywhere. Farmer Kalaba tends the field south of the farms. Careful: Kirin Tor Guards (55) stand north of the farms, on the road up toward Alterac: keep to the fields.", section="Hillsbrad Foothills (23-25)", zoneName="Hillsbrad Foothills", p=756, place="Hillsbrad Fields", was=2133}, -- 2196
  {t="C", q=527, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Farmhand", z=267, x=36.82, y=39.58, note="Kill Hillsbrad Farmhand", section="Hillsbrad Foothills (23-25)", zoneName="Hillsbrad Foothills", p=756, place="Hillsbrad Fields", was=2134}, -- 2197
