  {t="C", q=97538, name="Pigments for Paints", gv="Collect", gw="30 Mirkweed Pods", foreverOnly=true, z=406, x=48.5, y=40.2, note="Collect 30 Mirkweed Pods", tip="The Mirkweed grows on the bottom of Mirkfallon Lake, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath.", onQuest={97538}, section="The Barrens & Stonetalon Mountains (24-27)", zoneName="Stonetalon Mountains", p=816, place="Mirkweed", was=2269}, -- 2331
