  {t="C", q=1068, obj=2, name="Shredding Machines", z=406, x=64.09, y=56.62, note="XT:9", tip="Back down the Webwinder Path to Ziz Fizziks' hut, then east along the road toward Windshear Crag: XT:9 patrols the road just east of the fork, XT:4 the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them.", onQuest={1068}, section="The Barrens & Stonetalon Mountains (24-27)", zoneName="Stonetalon Mountains", p=821, place="Shredding Machines", was=2289}, -- 2351
  {t="C", q=1068, obj=1, name="Shredding Machines", z=406, x=67.2, y=46.69, note="XT:4", onQuest={1068}, section="The Barrens & Stonetalon Mountains (24-27)", zoneName="Stonetalon Mountains", p=821, place="Shredding Machines", was=2290}, -- 2352
  {t="C", q=1096, name="Gerenzo Wrenchwhistle", z=406, x=64.5, y=40.3, note="Gerenzo's Mechanical Arm, from Gerenzo Wrenchwhistle", tip="On east to Windshear Crag, past where XT:4 roams: Gerenzo Wrenchwhistle (27) stands at the top of the Venture Co. tower. Clear the Venture Co. on the way up. His Mechanical Arm is for Ziz.", onQuest={1096}, section="The Barrens & Stonetalon Mountains (24-27)", zoneName="Stonetalon Mountains", p=822, place="Gerenzo Wrenchwhistle", was=2291}, -- 2353
  {t="C", q=1086, name="The Flying Machine Airport", z=406, x=66.44, y=45.46, note="Place the Toxic Fogger on the Venture Co. Copter Pad", tip="The Venture Co. Copter Pad is the platform just south-east of Gerenzo's tower: place Zamah's Toxic Fogger on it. Zamah takes it back on the next guide's Thunder Bluff stop.", onQuest={1086}, section="The Barrens & Stonetalon Mountains (24-27)", zoneName="Stonetalon Mountains", p=823, place="The Flying Machine Airport", was=2292}, -- 2354
  {t="T", q=1096, name="Gerenzo Wrenchwhistle", z=406, x=58.99, y=62.6, target={kind="npc", id=4201, name="Ziz Fizziks"}, note="Ziz Fizziks, inside", tip="Back west to Ziz Fizziks' hut, on the way down to Malaka'jin.", ready=1096, section="The Barrens & Stonetalon Mountains (24-27)", zoneName="Stonetalon Mountains", p=824, place="Ziz Fizziks", was=2293}, -- 2355
