  {t="T", q=1534, name="Call of Water", z=17, x=43.42, y=77.41, target={kind="npc", id=5899, name="Brine"}, note="Brine", tip="Brine's hut stands on the ridge above the quilboar watering hole south of Camp Taurajo, on the road to the Great Lift.", classes={"Shaman"}, section="Ashenvale & Thousand Needles (27-29)", zoneName="The Barrens", p=880, place="Brine", was=2391}, -- 2455
  {t="A", q=220, name="Call of Water", z=17, x=43.42, y=77.41, target={kind="npc", id=5899, name="Brine"}, note="for Islen Waterseer, south of Ratchet: next guide", classes={"Shaman"}, section="Ashenvale & Thousand Needles (27-29)", zoneName="The Barrens", p=880, place="Brine", was=2392}, -- 2456
  {t="T", q=5881, name="Calling in the Reserves", z=400, x=31.86, y=21.66, target={kind="npc", id=12576, name="Grish Longrunner"}, note="Grish Longrunner", tip="Grish Longrunner and Brave Moonhorn wait at the top of the Great Lift: Maggran's letter is for Grish, and Moonhorn's message goes down to Freewind Post with you.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=881, place="The Great Lift", was=2393}, -- 2457
  {t="A", q=4542, name="Message to Freewind Post", z=400, x=32.24, y=22.17, target={kind="npc", id=10079, name="Brave Moonhorn"}, note="Brave Moonhorn, at the top of the lift: Cliffwatcher Longhorn at Freewind Post", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=881, place="The Great Lift", was=2394}, -- 2458
  {t="G", text="Freewind Post's lift", z=400, x=44.9, y=48.9, section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=882, place="Freewind Post's lift"}, -- 2459
  {t="FP", text="Freewind Post flight path", tip="Ride the lift down, then follow the road east through the canyons to Freewind Post, a Tauren village on top of the mesas. Its lift is on the north side.", section="Ashenvale & Thousand Needles (27-29)", p=883, place="Freewind Post"}, -- 2460
