  {t="A", q=4881, name="Assassination Plot", optional=true, z=400, x=46.57, y=41.16, target={kind="item", id=12564, name="Assassination Note"}, section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=886, place="Galak centaurs", was=2410}, -- 2474
  {t="C", q=1197, obj=1, name="The Sacred Flame", z=400, x=42.0, y=31.5, note="Filled Etched Phial, at the Ancient Brazier", tip="Careful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame.", onQuest={1197}, section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=887, place="Splithoof Hold", was=2411}, -- 2475
  {t="C", q=1197, name="The Sacred Flame", z=400, x=42.0, y=31.5, note="Cloven Hoof, from the Ancient Brazier", onQuest={1197}, section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=887, place="Splithoof Hold", was=2412}, -- 2476
  {t="A", q=1149, name="Test of Faith", z=400, x=53.95, y=41.49, target={kind="npc", id=2986, name="Dorn Plainstalker"}, note="Dorn Plainstalker, below ground", tip="Dorn Plainstalker stands on a mesa top east of the Galak camps. Taking his Test of Faith puts you on a high cliff far to the west: follow the stone path to the end of the wooden planks and step off there, and you land safely. Jump from anywhere else and you fall to your death.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=888, place="Dorn Plainstalker", was=2413}, -- 2477
  {t="C", q=1149, name="Test of Faith", z=400, x=26.43, y=32.93, note="the end of the planks", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=888, place="Dorn Plainstalker", was=2414}, -- 2478
  {t="T", q=1149, name="Test of Faith", z=400, x=53.95, y=41.49, target={kind="npc", id=2986, name="Dorn Plainstalker"}, section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=888, place="Dorn Plainstalker", was=2415}, -- 2479
