  {t="A", q=5062, name="Sacred Fire", z=400, x=21.54, y=32.35, target={kind="npc", id=10428, name="Motega Firemane"}, note="Motega Firemane: the Incendia Agave grows among the Grimtotem camps below Darkcloud Pinnacle, on the way back east", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=895, place="Whitereach Post"}, -- 2503
  {t="T", q=4881, name="Assassination Plot", z=400, x=21.25, y=32.06, target={kind="npc", id=10638, name="Kanati Greycloud"}, note="Kanati Greycloud", tip="Only if the Galak Messenger dropped his plot for you: Kanati Greycloud stands at Whitereach Post.", onQuest={4881, 4966}, section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=896, place="Kanati Greycloud", was=2438}, -- 2504
  {t="A", q=4966, name="Protect Kanati Greycloud", z=400, x=21.25, y=32.06, target={kind="npc", id=10638, name="Kanati Greycloud"}, onQuest={4881, 4966}, section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=896, place="Kanati Greycloud", was=2439}, -- 2505
