  {t="C", q=509, name="Elixir of Agony", z=267, x=64.2, y=61.4, note="Mudsnout Blossoms", tip="South of the river's bend, the Mudsnout gnolls (26-28) camp in the hills above Dun Garok; the blossoms grow among their tents. The Shamans heal and call their friends: pull them first.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=937, place="Mudsnout Blossoms", was=2507}, -- 2581
  {t="G", text="North of Southshore", z=267, x=60.0, y=42.0, tip="From the blossoms, back north along the river and then west to Hillsbrad town, well north of Southshore (its guards are 55).", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=938, place="North of Southshore"}, -- 2582
  {t="C", q=529, obj=1, name="Battle of Hillsbrad", gv="Kill", gw="Blacksmith Verringtan", z=267, x=32.11, y=44.42, note="Kill Blacksmith Verringtan", tip="West across the foothills to Hillsbrad town: the smithy stands in the middle of it. Blacksmith Verringtan and his apprentices work at the forge; the Shipment of Iron is stacked beside it. Citizen Wilkes walks the west side of the town; Farmer Kalaba works the field south-east of the town.", notTurnedIn={529}, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=939, place="The smithy", was=2509}, -- 2583
  {t="C", q=529, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Apprentice Blacksmith", z=267, x=31.61, y=44.48, note="Kill Hillsbrad Apprentice Blacksmith", notTurnedIn={529}, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=939, place="The smithy", was=2510}, -- 2584
