  {t="C", q=567, obj=4, name="Dangerous!", gv="Kill", gw="Farmer Kalaba", z=267, x=35.88, y=46.57, note="Kill Farmer Kalaba", notTurnedIn={529}, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=939, place="The smithy", was=2513}, -- 2587
