  {t="T", q=509, name="Elixir of Agony", z=267, x=61.44, y=19.06, target={kind="npc", id=2216, name="Apothecary Lydon"}, note="Apothecary Lydon, inside", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=940, place="Tarren Mill", was=2516}, -- 2590
  {t="A", q=513, name="Elixir of Agony", z=267, x=61.44, y=19.06, target={kind="npc", id=2216, name="Apothecary Lydon"}, note="for Master Apothecary Faranell, on the Undercity stop at the end of this guide", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=940, place="Tarren Mill", was=2517}, -- 2591
  {t="A", q=552, name="Helcular's Revenge", z=267, x=63.88, y=19.66, target={kind="npc", id=2429, name="Novice Thaivand"}, note="Novice Thaivand, in the town: Helcular's Rod, from the yetis on the way to the town hall", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=940, place="Tarren Mill", was=2518}, -- 2592
  {t="A", q=546, name="Souvenirs of Death", z=267, x=62.11, y=19.7, target={kind="npc", id=2418, name="Deathguard Samsa"}, note="Deathguard Samsa, beside Christoph Jeffcoat: Hillsbrad Human Skulls, from the townsfolk and miners this guide fights next", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=940, place="Tarren Mill", was=2140}, -- 2593
  {t="C", q=552, name="Helcular's Revenge", gv="Collect", gw="Helcular's Rod", z=267, x=44.5, y=29.4, note="Collect Helcular's Rod", tip="West of Tarren Mill, the Cave and Ferocious Yetis (30-32) fill the Foothill Caverns in the hills; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but they hit hard and come in pairs.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=941, place="Helcular's Rod", was=2519}, -- 2594
  {t="C", q=532, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Councilman", z=267, x=32.06, y=42.43, note="Kill Hillsbrad Councilman", tip="On to Hillsbrad town, south-west of the yeti caves. The town hall is on the town's west side: Magistrate Burnside (30) and Clerk Horrace Whitesteed are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town. Every Hillsbrad human you kill from here on can drop a skull for Samsa: keep them.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=942, place="Town hall", was=2520}, -- 2595
  {t="C", q=532, obj=3, name="Battle of Hillsbrad", z=267, x=29.73, y=41.75, note="Hillsbrad Proclamation, inside", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=942, place="Town hall", was=2521}, -- 2596
  {t="C", q=532, obj=4, name="Battle of Hillsbrad", z=267, x=29.52, y=41.53, note="Inside", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=942, place="Town hall", was=2522}, -- 2597
  {t="C", q=567, obj=1, name="Dangerous!", z=267, x=29.51, y=42.41, note="Inside", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=942, place="Town hall", was=2523}, -- 2598
  {t="C", q=532, obj=1, name="Battle of Hillsbrad", z=267, x=29.67, y=41.64, note="Inside", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=942, place="Town hall", was=2524}, -- 2599
  {t="T", q=532, name="Battle of Hillsbrad", z=267, x=62.33, y=20.45, target={kind="npc", id=2215, name="High Executor Darthalia"}, note="High Executor Darthalia", tip="Back east to Tarren Mill.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=943, place="Tarren Mill", was=2525}, -- 2600
