  {t="T", q=552, name="Helcular's Revenge", z=267, x=63.88, y=19.66, target={kind="npc", id=2429, name="Novice Thaivand"}, note="Novice Thaivand", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=943, place="Tarren Mill", was=2527}, -- 2602
  {t="N", text="Thaivand's next errand, the flames, sends you among the Mountain and Giant Yetis (32-34) and to Helcular's grave inside Southshore: leave it.", section="Hillsbrad Foothills (29-31)", p=943, place="Tarren Mill"}, -- 2603
  {t="G", text="Azurelode Mine", z=267, x=28.5, y=55.0, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=944, place="Hillsbrad Foothills"}, -- 2604
  {t="C", q=539, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Miner", z=267, x=28.3, y=54.8, note="Kill Hillsbrad Miner", tip="Head south-west past Hillsbrad town to the Azurelode Mine. Miners (26-27) work the tunnels; Foreman Bonds (30) and Miner Hackett (29) are deep inside. Keep killing Miners until Samsa's thirty skulls are in your bags: most Hillsbrad humans drop one.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=945, place="Azurelode Mine", was=2530}, -- 2605
  {t="C", q=567, obj=3, name="Dangerous!", gv="Kill", gw="Miner Hackett", z=267, x=31.8, y=52.7, note="Kill Miner Hackett", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=945, place="Azurelode Mine", was=2531}, -- 2606
  {t="C", q=539, obj=1, name="Battle of Hillsbrad", z=267, x=31.21, y=56.01, note="Inside Azurelode Mine", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=945, place="Azurelode Mine", was=2532}, -- 2607
  {t="C", q=546, obj=1, name="Souvenirs of Death", z=267, x=31.21, y=56.01, note="Hillsbrad Human Skull, from the Miners and every Hillsbrad human", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=945, place="Azurelode Mine", was=2147}, -- 2608
  {t="C", q=7321, obj=1, name="Soothing Turtle Bisque", gv="Collect", gw="Turtle Meat", z=267, x=68.0, y=24.0, note="Collect Turtle Meat", tip="Still short of ten Turtle Meat? The Snapjaws line the river just east of Tarren Mill, a short way from town.", onQuest={7321}, hasBelow={3712, 10}, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=946, place="Finish the Turtle Meat", was=2535}, -- 2609
  {t="T", q=7321, name="Soothing Turtle Bisque", z=267, x=62.29, y=19.04, target={kind="npc", id=2393, name="Christoph Jeffcoat"}, note="Christoph Jeffcoat", tip="North-east back to Tarren Mill, passing well north of Southshore (its guards are 55).", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=947, place="Tarren Mill", was=2536}, -- 2610
  {t="T", q=539, name="Battle of Hillsbrad", z=267, x=62.33, y=20.45, target={kind="npc", id=2215, name="High Executor Darthalia"}, note="High Executor Darthalia: her next Battle of Hillsbrad, and Deathguard Humbert's sword, are elite group quests at Dun Garok: take them only with a group", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=947, place="Tarren Mill", was=2537}, -- 2611
  {t="T", q=567, name="Dangerous!", z=267, x=62.33, y=20.45, target={kind="npc", id=2215, name="High Executor Darthalia"}, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=947, place="Tarren Mill", was=2538}, -- 2612
