  {t="A", q=533, name="Infiltration", z=267, x=63.24, y=20.66, target={kind="npc", id=2229, name="Krusk"}, note="Krusk, inside: Infiltration, worked on the 38-39 visit (its Syndicate are 32-35)", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=947, place="Tarren Mill", was=2539}, -- 2614
  {t="N", text="Keep Infiltration in your log: its Syndicate (32-35) are over you now, and the 38-39 guide (Alterac and Arathi) works it on its first Tarren Mill loop.", section="Hillsbrad Foothills (29-31)", p=947, place="Tarren Mill"}, -- 2615
  {t="G", text="Snapjaws", z=267, x=68.0, y=24.0, tip="Magus Wordeen Voidglare's quests in the inn and Alliance Relations in Orgrimmar, the next guide's first stop, are offered from level 30. Still short of 30 after these hand-ins? The Snapjaws (29-31) line the river just east and south of Tarren Mill: kill them until level 30, then walk back into town. Or, with a group, run the Excavation Site dungeon (in the Wetlands) instead.", lvlBelow=30.0, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=948, place="Level 30"}, -- 2616
  {t="N", text="Reach level 30", note="grind on Snapjaw", lvlBelow=30.0, section="Hillsbrad Foothills (29-31)", p=948, place="Level 30"}, -- 2617
  {t="A", q=544, name="Prison Break In", z=267, x=61.6, y=20.85, target={kind="npc", id=2410, name="Magus Wordeen Voidglare"}, note="Magus Wordeen Voidglare, inside: Prison Break In, for the 38-39 visit (the Dalaran crater's traitors are 33-35)", tip="Magus Wordeen Voidglare and Keeper Bel'varil are inside the inn, Tallow just outside it. Their quests are offered from level 30; below it, the 38-39 guide's first Tarren Mill stop takes them.", lvlMin=30.0, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=949, place="Voidglare, Bel'varil and Tallow", was=2541}, -- 2618
  {t="A", q=93680, name="Key to the City", foreverOnly=true, z=267, x=61.6, y=20.85, target={kind="npc", id=2410, name="Magus Wordeen Voidglare"}, note="Magus Wordeen Voidglare: Key to the City, with Prison Break In on the 38-39 visit", lvlMin=30.0, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=949, place="Voidglare, Bel'varil and Tallow", was=2542}, -- 2619
  {t="A", q=556, name="Stone Tokens", z=267, x=61.5, y=20.93, target={kind="npc", id=2437, name="Keeper Bel'varil"}, note="Keeper Bel'varil, inside: Stone Tokens, with the crater on the 38-39 visit", lvlMin=30.0, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=949, place="Voidglare, Bel'varil and Tallow", was=2543}, -- 2620
  {t="A", q=676, name="The Hammer May Fall", z=267, x=61.87, y=19.57, target={kind="npc", id=2770, name="Tallow"}, note="Tallow, outside the inn: the Boulderfist ogres (32-34) on the 38-39 Arathi visit", lvlMin=30.0, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=949, place="Voidglare, Bel'varil and Tallow", was=2544}, -- 2621
  {t="N", text="Keep these in your log: their camps are two to four levels over you now, and the 38-39 guide works them on its first Tarren Mill loop and in Hammerfall.", lvlMin=30.0, section="Hillsbrad Foothills (29-31)", p=949, place="Voidglare, Bel'varil and Tallow"}, -- 2622
  {t="A", q=541, name="Battle of Hillsbrad", group=true, z=267, x=62.33, y=20.45, target={kind="npc", id=2215, name="High Executor Darthalia"}, note="High Executor Darthalia", tip="Darthalia's last battle is at Dun Garok, the dwarven keep south-east of Southshore: every dwarf there is elite (28-32), Captain Ironhill too. Great XP if you have a group for it.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=950, place="Battle of Hillsbrad with a group", was=2546}, -- 2623
  {t="A", q=547, name="Humbert's Sword", group=true, z=267, x=62.76, y=20.21, target={kind="npc", id=2419, name="Deathguard Humbert"}, note="Deathguard Humbert", tip="Deathguard Humbert's sword drops from the same Dun Garok dwarves (about one in twelve).", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=951, place="Humbert's Sword with a group", was=2547}, -- 2624
  {t="C", q=541, obj=1, name="Battle of Hillsbrad", gv="Kill", gw="Dun Garok Mountaineer", z=267, x=71.2, y=79.0, note="Kill Dun Garok Mountaineer", tip="Clear Dun Garok from the gate in; the dwarves run for help at 30% health.", onQuest={541, 547}, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=952, place="Dun Garok", was=2548}, -- 2625
  {t="C", q=541, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Dun Garok Rifleman", z=267, x=71.0, y=78.3, note="Kill Dun Garok Rifleman", onQuest={541, 547}, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=952, place="Dun Garok", was=2549}, -- 2626
