  {t="T", q=513, name="Elixir of Agony", z=1497, x=48.82, y=69.28, target={kind="npc", id=2055, name="Master Apothecary Faranell"}, note="Master Apothecary Faranell", tip="Master Apothecary Faranell stands in the Apothecarium, in the Royal Quarter.", section="Hillsbrad Foothills (29-31)", zoneName="Undercity", p=956, place="Master Apothecary Faranell", was=2558}, -- 2635
