  {t="A", q=97985, name="Thundering Hearts", group=true, foreverOnly=true, z=1497, x=49.11, y=70.14, target={kind="npc", id=270038, name="Calder Gray"}, note="Calder Gray: back to him on the next Undercity stop, at about 38", tip="Calder Gray stands in the Apothecarium. His Thundering Hearts is for Stormheart, a level 30 elite who walks the canyon east of Freewind Post, on the next guide's way to the Shimmering Flats.", section="Hillsbrad Foothills (29-31)", zoneName="Undercity", p=958, place="Calder Gray", was=2561}, -- 2638
  {t="TR", text="Train at your class trainer", tip="Train while you are in the Undercity: the trainers stand in the War Quarter, the Rogues' Quarter and the Magic Quarter (Paladins: Garen Largo).", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Hillsbrad Foothills (29-31)", p=959, place="Undercity trainers"}, -- 2639
