  {t="A", q=1431, name="Alliance Relations", z=1637, x=51.3, y=45.9, target={kind="npc", id=5639, name="Craven Drok"}, note="Craven Drok: offered from level 30", tip="The zeppelin lands at the tower outside Orgrimmar's main gate. Craven Drok walks the Drag: if he isn't at the arrow, look along its streets to the south-west. Keldran stands in the Valley of Spirits on the west side of the city.", lvlMin=30.0, section="Thousand Needles & Desolace (30-34)", zoneName="Orgrimmar", p=961, place="Alliance Relations", was=2564}, -- 2641
