  {t="C", q=97985, name="Thundering Hearts", group=true, foreverOnly=true, z=400, x=60.51, y=57.78, note="Stormheart's Still-beating Heart, from Stormheart", tip="Stormheart walks the canyon road east of Freewind Post's lift, on the way to the salt flats: kill him for his heart.", section="Thousand Needles & Desolace (30-34)", zoneName="Thousand Needles", p=981, place="Stormheart", was=2602}, -- 2679
