  {t="A", q=1365, name="Khan Dez'hepah", z=405, x=56.19, y=59.57, target={kind="npc", id=5395, name="Felgur Twocuts"}, note="Felgur Twocuts", tip="Felgur stands in the post, Nataka Longhorn up on its rise; Takata Steelblade and Maurin Bonesplitter wait on the rise west of it, above the Kodo Graveyard.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=998, place="Ghost Walker Post", was=2646}, -- 2723
