  {t="A", q=5741, name="Sceptre of Light", z=405, x=38.88, y=27.16, target={kind="npc", id=11863, name="Azore Aldamort"}, note="Azore Aldamort", tip="From the rise, north-west across the plain to the ruined tower of Ethel Rethor: Azore Aldamort waits inside. His errand is in Thunder Axe Fortress, the next stop; he takes it back on the walk up the coast later in this guide.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1001, place="Ethel Rethor", was=2661}, -- 2730
  {t="C", q=1435, name="The Burning of Spirits", gv="Collect", gw="Infused Burning Gem", z=405, x=55.0, y=26.5, note="Collect Infused Burning Gem", tip="Head east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it. Leave the red Hand of Iruxos Crystal for now: its Demon Spirit is 37, and the second Desolace visit comes back for it.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1002, place="Thunder Axe Fortress", was=2662}, -- 2731
  {t="C", q=5741, name="Sceptre of Light", z=405, x=55.2, y=30.1, note="On the top floor", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1002, place="Thunder Axe Fortress", was=2663}, -- 2732
  {t="N", text="Collect Flayed Demon Skin", optional=true, section="Thousand Needles & Desolace (30-34)", p=1002, place="Thunder Axe Fortress"}, -- 2733
  {t="A", q=1480, name="The Corrupter", optional=true, z=405, x=55.2, y=30.1, target={kind="item", id=20310, name="Flayed Demon Skin"}, section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1002, place="Thunder Axe Fortress", was=2665}, -- 2734
  {t="C", q=1434, obj=1, name="Befouled by Satyr", gv="Kill", gw="Hatefury Rogue", z=405, x=73.6, y=25.46, note="Kill Hatefury Rogue", tip="Careful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1003, place="Sargeron", was=2674}, -- 2735
  {t="C", q=1434, obj=2, name="Befouled by Satyr", gv="Kill", gw="Hatefury Felsworn", z=405, x=74.44, y=24.35, note="Kill Hatefury Felsworn", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1003, place="Sargeron", was=2675}, -- 2736
  {t="C", q=1434, obj=3, name="Befouled by Satyr", gv="Kill", gw="Hatefury Betrayer", z=405, x=75.85, y=24.49, note="Kill Hatefury Betrayer", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1003, place="Sargeron", was=2676}, -- 2737
  {t="C", q=1434, obj=4, name="Befouled by Satyr", gv="Kill", gw="Hatefury Hellcaller", z=405, x=76.79, y=25.57, note="Kill Hatefury Hellcaller", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1003, place="Sargeron", was=2677}, -- 2738
  {t="C", q=1365, name="Khan Dez'hepah", gv="Collect", gw="Khan Dez'hepah's Head", z=405, x=73.2, y=41.8, note="Collect Khan Dez'hepah's Head", tip="Careful: Khan Dez'hepah is level 35, about two levels over you here, and Kolkar Battle Lords call nearby allies within 30 yd once they fall to 20% health.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1004, place="Khan Dez'hepah", was=2683}, -- 2739
  {t="T", q=1434, name="Befouled by Satyr", z=405, x=52.57, y=54.39, target={kind="npc", id=5641, name="Takata Steelblade"}, note="Takata Steelblade", tip="South-west down the road to the post: Takata and Maurin on the rise west of it, Felgur and Gurda Wildmane side by side in the post.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1005, place="Ghost Walker Post", was=2684}, -- 2740
  {t="T", q=1435, name="The Burning of Spirits", z=405, x=52.25, y=53.44, target={kind="npc", id=4498, name="Maurin Bonesplitter"}, note="Maurin Bonesplitter", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1005, place="Ghost Walker Post", was=2685}, -- 2741
