  {t="A", q=1436, name="Alliance Relations", z=405, x=52.57, y=54.39, target={kind="npc", id=5641, name="Takata Steelblade"}, note="Takata Steelblade: for Keldran in Orgrimmar, next guide", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1005, place="Ghost Walker Post", was=2687}, -- 2743
  {t="N", text="Takata's next errand sends you after a demon lord with an elite guard, and Maurin's next Corrupter errand back to Sargeron: leave them.", section="Thousand Needles & Desolace (30-34)", p=1005, place="Ghost Walker Post"}, -- 2744
  {t="T", q=1365, name="Khan Dez'hepah", z=405, x=56.19, y=59.57, target={kind="npc", id=5395, name="Felgur Twocuts"}, note="Felgur Twocuts", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1005, place="Ghost Walker Post", was=2689}, -- 2745
  {t="A", q=1366, name="Centaur Bounty", z=405, x=56.19, y=59.57, target={kind="npc", id=5395, name="Felgur Twocuts"}, note="Felgur Twocuts: the Magram centaurs south-east of the post, after Smeed's kodos", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1005, place="Ghost Walker Post", was=2874}, -- 2746
  {t="A", q=93225, name="Carved Centaur Totems", foreverOnly=true, z=405, x=56.29, y=59.68, target={kind="npc", id=5412, name="Gurda Wildmane"}, note="Gurda Wildmane: her totems drop from the same Magram centaurs", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1005, place="Ghost Walker Post", was=2873}, -- 2747
  {t="N", text="Kodo Kombobulator", z=405, x=51.0, y=58.5, note="on an Aged, Dying or Ancient Kodo in the graveyard; don't kill it", tip="Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo in the graveyard and walk the tamed kodo back to Smeed. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time. Careful: leave the kodo skulls on the ground alone: opening one raises a Kodo Apparition (37-38) that hits hard.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1006, place="Kodo Graveyard"}, -- 2748
  {t="C", q=5561, obj=1, name="Kodo Roundup", z=405, x=60.6, y=61.6, note="the tamed kodo, at Smeed's camp: talk to it, five times", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1006, place="Kodo Graveyard", was=2654}, -- 2749
  {t="T", q=5561, name="Kodo Roundup", z=405, x=60.86, y=61.86, target={kind="npc", id=11596, name="Smeed Scrabblescrew"}, note="Smeed Scrabblescrew", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1007, place="Scrabblescrew's Camp", was=2655}, -- 2750
  {t="C", q=1366, name="Centaur Bounty", z=405, x=66.0, y=71.0, note="Centaur Ear, from the Magram Scouts, Outrunners and Wranglers", tip="Careful: the Stormers and Pack Runners (34-35), Marauders and Maulers (35-36) and the Bonepaws (37-38) hold the middle and south of the camp: stay on its north-western edge and pull one at a time.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1008, place="Magram Village", was=2876}, -- 2751
  {t="C", q=93225, obj=1, name="Carved Centaur Totems", foreverOnly=true, z=405, x=66.0, y=71.0, note="Carved Centaur Totem, from the same centaurs", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1008, place="Magram Village", was=2875}, -- 2752
  {t="T", q=1366, name="Centaur Bounty", z=405, x=56.19, y=59.57, target={kind="npc", id=5395, name="Felgur Twocuts"}, note="Felgur Twocuts", tip="Back north-west to the post, on your way west.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1009, place="Ghost Walker Post", was=2882}, -- 2753
  {t="T", q=93225, name="Carved Centaur Totems", foreverOnly=true, z=405, x=56.29, y=59.68, target={kind="npc", id=5412, name="Gurda Wildmane"}, note="Gurda Wildmane", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1009, place="Ghost Walker Post", was=2881}, -- 2754
  {t="SH", text="Shadowprey Village", z=405, x=24.09, y=68.21, note="Innkeeper Sikewa", tip="Head west to the troll village on the coast, keeping clear of the Gelkis Village on the way.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1010, place="Shadowprey Village"}, -- 2755
  {t="A", q=5763, name="Hunting in Stranglethorn", z=405, x=25.05, y=72.27, target={kind="npc", id=11877, name="Roon Wildmane"}, note="Roon Wildmane: for Hemet Nesingwary in Stranglethorn, next guide", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1010, place="Shadowprey Village", was=2658}, -- 2756
  {t="A", q=6142, name="Clam Bait", z=405, x=22.64, y=71.97, target={kind="npc", id=12031, name="Mai'Lahii"}, note="Mai'Lahii", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1010, place="Shadowprey Village", was=2659}, -- 2757
  {t="FP", text="Shadowprey Village flight path", note="Thalon, at the village's south-west end", section="Thousand Needles & Desolace (30-34)", p=1010, place="Shadowprey Village"}, -- 2758
  {t="A", q=6143, name="Other Fish to Fry", z=405, x=23.32, y=72.87, target={kind="npc", id=12340, name="Drulzegar Skraghook"}, note="Drulzegar Skraghook", tip="Drulzegar stands at the village's south end, near Mai'Lahii. At your level his Other Fish to Fry fits the walk north along the coast: the southern half of Sar'theris Strand, from level 34.", lvlMin=33.5, section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1011, place="Drulzegar Skraghook", was=2872}, -- 2759
  {t="T", q=5741, name="Sceptre of Light", z=405, x=38.88, y=27.16, target={kind="npc", id=11863, name="Azore Aldamort"}, note="Azore Aldamort", tip="North along the coast, then inland to Azore's tower. The coast's clams and naga come next, on one walk north to Ranazjar Isle.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1012, place="Ethel Rethor", was=2666}, -- 2760
  {t="N", text="Azore's next errand, the Book of the Ancients, needs Lord Kragaru (38) out on Ranazjar Isle: leave it, he is over your level.", section="Thousand Needles & Desolace (30-34)", p=1012, place="Ethel Rethor"}, -- 2761
  {t="A", q=6161, name="Claim Rackmore's Treasure!", z=405, x=36.07, y=30.41, target={kind="object", id=177787, name="Rackmore's Log"}, note="Rackmore's Log", tip="Rackmore's Log lies on the ground just south-west of Azore's tower, on the way down to the shore: read it. Its two keys drop only while you have the quest.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1013, place="Rackmore's Log", was=2668}, -- 2762
  {t="C", q=6142, obj=1, name="Clam Bait", z=405, x=30.6, y=31.9, note="Giant Softshell Clams, on the sea floor; Soft-shelled Clam: open it in your bags", tip="The Drysnap Crawlers and Pincers on the same beach carry Rackmore's Silver Key, about one in seven.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1014, place="Clam beds", was=2669}, -- 2763
  {t="C", q=6142, name="Clam Bait", z=405, x=30.6, y=31.9, note="Underwater", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1014, place="Clam beds", was=2670}, -- 2764
  {t="C", q=6161, obj=1, name="Claim Rackmore's Treasure!", z=405, x=33.4, y=30.1, note="Rackmore's Silver Key, from the Drysnap crabs", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1014, place="Clam beds", was=2671}, -- 2765
  {t="C", q=6161, obj=2, name="Claim Rackmore's Treasure!", z=405, x=35.91, y=28.84, note="Rackmore's Golden Key, from the Slitherblade naga", tip="Careful: the Myrmidons (34-35) hold the beach's northern half with the Sea Witches and Oracles (34-36, casters), up to two over you at 33: work the Naga and Sorceresses (32-33) of the southern half until the key drops, and leave the north for the second Desolace visit, at about 37.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1015, place="Sar'theris Strand", was=2672}, -- 2766
  {t="C", q=6143, obj=1, name="Other Fish to Fry", z=405, x=32.2, y=21.5, note="Slitherblade Myrmidon, in the strand's southern half", tip="Careful: the northern half belongs to the Sea Witches (35-36, casters) and, at its tip, the Tidehunters (36-37): keep south of the middle of the beach.", lvlMin=34.0, onQuest={6143}, section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1016, place="Sar'theris Strand: Other Fish to Fry", was=2885}, -- 2767
  {t="C", q=6143, obj=2, name="Other Fish to Fry", z=405, x=32.74, y=23.92, note="Slitherblade Naga", lvlMin=34.0, onQuest={6143}, section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1016, place="Sar'theris Strand: Other Fish to Fry", was=2886}, -- 2768
  {t="C", q=6143, obj=3, name="Other Fish to Fry", z=405, x=32.94, y=23.32, note="Slitherblade Sorceress", lvlMin=34.0, onQuest={6143}, section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1016, place="Sar'theris Strand: Other Fish to Fry", was=2887}, -- 2769
  {t="T", q=6161, name="Claim Rackmore's Treasure!", z=405, x=30.0, y=8.7, target={kind="object", id=177786, name="Rackmore's Chest"}, note="Rackmore's Chest", tip="Swim out to Ranazjar Isle off the far northern tip: Rackmore's Chest stands on the shore beside the Serpent Statue. Open it with both keys; leave the statue alone.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1017, place="Rackmore's Chest", was=2673}, -- 2770
  {t="T", q=6142, name="Clam Bait", z=405, x=22.64, y=71.97, target={kind="npc", id=12031, name="Mai'Lahii"}, note="Mai'Lahii", tip="Hearth to Shadowprey (you bound it on the way in), or walk back south along the coast.", section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1018, place="Shadowprey Village", was=2692}, -- 2771
  {t="N", text="Taiga's Hand of Iruxos, Drulzegar's Other Fish to Fry (unless you did it on the strand) and Desolace's other 37-40 quests wait for the second visit, at about 37: the next guides fly to Orgrimmar and take the zeppelin to Stranglethorn Vale.", section="Thousand Needles & Desolace (30-34)", p=1018, place="Shadowprey Village"}, -- 2772
  {t="T", q=6143, name="Other Fish to Fry", z=405, x=23.32, y=72.87, target={kind="npc", id=12340, name="Drulzegar Skraghook"}, note="Drulzegar Skraghook, near Mai'Lahii", ready=6143, section="Thousand Needles & Desolace (30-34)", zoneName="Desolace", p=1019, place="Drulzegar Skraghook", was=2890}, -- 2773
