  {t="T", q=1436, name="Alliance Relations", z=1637, x=22.56, y=52.63, target={kind="npc", id=5640, name="Keldran"}, note="Keldran", tip="Keldran stands in the Valley of Spirits on the west side of the city.", section="Stranglethorn Vale (34-36)", zoneName="Orgrimmar", p=1023, place="Keldran", was=2700}, -- 2780
  {t="TR", text="Train at your class trainer", tip="Train while you are in the city.", classes={"Warrior", "Hunter", "Rogue", "Priest", "Shaman", "Mage", "Warlock"}, section="Stranglethorn Vale (34-36)", p=1024, place="Orgrimmar trainers"}, -- 2781
  {t="G", text="Orgrimmar flight master", z=17, x=45.3, y=63.7, tip="Booty Bay first: the goblins' boat sails there from Ratchet, and every Booty Bay quest is for the north of the vale, which you then walk up into.", section="Stranglethorn Vale (34-36)", zoneName="The Barrens", p=1025, place="Fly to Ratchet"}, -- 2782
  {t="F", text="Ratchet", section="Stranglethorn Vale (34-36)", p=1025, place="Fly to Ratchet"}, -- 2783
