  {t="A", q=1180, name="Goblin Sponsorship", z=17, x=62.68, y=36.23, target={kind="npc", id=3391, name="Gazlowe"}, note="Gazlowe: for Wharfmaster Lozgil in Booty Bay, where the boat goes", section="Stranglethorn Vale (34-36)", zoneName="The Barrens", p=1026, place="Ratchet", was=2705}, -- 2785
  {t="T", q=1111, name="Wharfmaster Dizzywig", z=17, x=63.35, y=38.45, target={kind="npc", id=3453, name="Wharfmaster Dizzywig"}, note="Wharfmaster Dizzywig, on the docks", section="Stranglethorn Vale (34-36)", zoneName="The Barrens", p=1026, place="Ratchet", was=2706}, -- 2786
  {t="N", text="Dizzywig's parts go back to Kravel in the Shimmering Flats, off the route: leave them.", section="Stranglethorn Vale (34-36)", p=1026, place="Ratchet"}, -- 2787
  {t="G", text="Boat to Booty Bay", z=17, x=63.4, y=38.5, section="Stranglethorn Vale (34-36)", zoneName="The Barrens", p=1027, place="Boat to Booty Bay"}, -- 2788
  {t="T", q=1180, name="Goblin Sponsorship", z=33, x=26.35, y=73.56, target={kind="npc", id=4631, name="Wharfmaster Lozgil"}, note="Wharfmaster Lozgil, on the pier", tip="Wharfmaster Lozgil stands on the pier where the boat docks. Drizzlik's shop is in the building east of the inn; Crank Fizzlebub is on the inn's bottom floor, Baron Revilgaz, Kebok and Krazek upstairs, Gringer the flight master on the upper deck.", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1028, place="Booty Bay", was=2709}, -- 2789
