  {t="A", q=568, name="The Defense of Grom'gol", z=33, x=32.17, y=28.9, target={kind="npc", id=2464, name="Commander Aggro'gosh"}, note="Commander Aggro'gosh", tip="Leave Booty Bay through the tunnel and follow the road north to Grom'gol, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level.", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1029, place="Grom'gol", was=2719}, -- 2799
