  {t="A", q=583, name="Welcome to the Jungle", z=33, x=35.66, y=10.53, target={kind="npc", id=716, name="Barnil Stonepot"}, note="Barnil Stonepot", tip="Follow the road north out of Grom'gol; Nesingwary's hunting camp sits on the hill north-east of the river. Krazek wants it investigated: walk among its tents. From here on, keep every page of The Green Hills of Stranglethorn you loot: Barnil takes them on your next Stranglethorn visit.", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1030, place="Nesingwary's camp", was=2725}, -- 2805
  {t="T", q=583, name="Welcome to the Jungle", z=33, x=35.66, y=10.81, target={kind="npc", id=715, name="Hemet Nesingwary"}, note="Hemet Nesingwary", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1030, place="Nesingwary's camp", was=2726}, -- 2806
