  {t="C", q=201, name="Investigate the Camp", z=33, x=35.65, y=10.59, section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1030, place="Nesingwary's camp", was=2732}, -- 2812
  {t="C", q=575, name="Supply and Demand", gv="Collect", gw="Large River Crocolisk Skin", z=33, x=34.58, y=10.46, note="Collect Large River Crocolisk Skin", tip="River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A Pendant of Myzrael is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight.", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1031, place="Nesingwary's Expedition: kill these as you meet them", was=2733}, -- 2813
  {t="C", q=185, name="Tiger Mastery", gv="Kill", gw="Young Stranglethorn Tiger", z=33, x=34.07, y=11.33, note="Kill Young Stranglethorn Tiger", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1031, place="Nesingwary's Expedition: kill these as you meet them", was=2734}, -- 2814
