  {t="A", q=191, name="Panther Mastery", z=33, x=35.55, y=10.55, target={kind="npc", id=718, name="Sir S. J. Erlgadin"}, section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1032, place="Nesingwary's camp", was=2742}, -- 2822
  {t="C", q=186, name="Tiger Mastery", gv="Kill", gw="Stranglethorn Tiger", z=33, x=45.0, y=15.0, note="Kill Stranglethorn Tiger", tip="Stranglethorn Tigers (32) roam the hills west of the camp and east of it toward the lake: the arrow takes the eastern ones, on your way to the geologists. Panthers (32) roam the clearings west and south-west of the camp. The Venture Co. Geologists (34-36), who carry the Tumbled Crystals, work the camps by Lake Nazferiti, south-east of the camp. Careful: Venture Co. Agents (39) stand among the geologists in the western camps by the Venture Co. house: work the eastern camps, away from them.", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1033, place="Stranglethorn Vale: kill these as you meet them", was=2743}, -- 2823
  {t="C", q=213, name="Hostile Takeover", z=33, x=46.3, y=21.4, note="Tumbled Crystals, from the geologists of the eastern camps", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1033, place="Stranglethorn Vale: kill these as you meet them", was=2744}, -- 2824
  {t="C", q=191, name="Panther Mastery", gv="Kill", gw="Panther", z=33, x=45.69, y=10.32, note="Kill Panther", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1033, place="Stranglethorn Vale: kill these as you meet them", was=2745}, -- 2825
  {t="T", q=191, name="Panther Mastery", z=33, x=35.55, y=10.55, target={kind="npc", id=718, name="Sir S. J. Erlgadin"}, note="Sir S. J. Erlgadin", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1034, place="Nesingwary's camp", was=2746}, -- 2826
