  {t="C", q=97331, name="Zimmix's Great Escape", foreverOnly=true, z=33, x=26.8, y=11.4, section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1039, place="Zimmix Sputterspark", was=2762}, -- 2842
  {t="N", text="Escort Zimmix out of the ruins and keep him alive: Lozgil takes the news once he is safe.", section="Stranglethorn Vale (34-36)", p=1039, place="Zimmix Sputterspark"}, -- 2843
  {t="T", q=194, name="Raptor Mastery", z=33, x=35.66, y=10.81, target={kind="npc", id=715, name="Hemet Nesingwary"}, note="Hemet Nesingwary", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1040, place="Nesingwary's camp", was=2764}, -- 2844
