  {t="A", q=1203, name="Jarl Needs a Blade", optional=true, z=15, x=55.44, y=26.27, target={kind="npc", id=4792, name="\"Swamp Eye\" Jarl"}, note="only if you carry a Moonsteel Broadsword (Blacksmithing or the Auction House)", section="Dustwallow Marsh & Desolace (36-37)", zoneName="Dustwallow Marsh", p=1072, place="Swamp Eye Jarl", was=2852}, -- 2934
  {t="T", q=1203, name="Jarl Needs a Blade", optional=true, z=15, x=55.44, y=26.27, target={kind="npc", id=4792, name="\"Swamp Eye\" Jarl"}, section="Dustwallow Marsh & Desolace (36-37)", zoneName="Dustwallow Marsh", p=1072, place="Swamp Eye Jarl", was=2853}, -- 2935
  {t="C", q=1202, obj=1, name="The Theramore Docks", z=15, x=71.5, y=51.2, note="Underwater", tip="South-east from the manor to Theramore Isle: the Captain's Footlocker lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57, and a death here is a long run back from the spirit healer. Young Murk Threshers (40-41) circle in the water around the docks: grab the footlocker and swim straight out.", section="Dustwallow Marsh & Desolace (36-37)", zoneName="Dustwallow Marsh", p=1073, place="The Theramore Docks", was=2854}, -- 2936
  {t="T", q=1177, name="Hungry!", z=15, x=35.15, y=38.26, target={kind="npc", id=4503, name="Mudcrush Durtfeet"}, note="Mudcrush Durtfeet", tip="Head back west to Brackenwall with the head: Mudcrush Durtfeet stands at the south edge of the village where the road comes in, Nazeer Bloodpike and Krog in the village.", section="Dustwallow Marsh & Desolace (36-37)", zoneName="Dustwallow Marsh", p=1074, place="Brackenwall Village", was=2855}, -- 2937
  {t="T", q=1202, name="The Theramore Docks", z=15, x=35.21, y=30.66, target={kind="npc", id=4791, name="Nazeer Bloodpike"}, note="Nazeer Bloodpike", section="Dustwallow Marsh & Desolace (36-37)", zoneName="Dustwallow Marsh", p=1074, place="Brackenwall Village", was=2856}, -- 2938
  {t="T", q=1239, name="The Severed Head", z=15, x=35.21, y=30.66, target={kind="npc", id=4791, name="Nazeer Bloodpike"}, note="Nazeer Bloodpike", section="Dustwallow Marsh & Desolace (36-37)", zoneName="Dustwallow Marsh", p=1074, place="Brackenwall Village", was=2857}, -- 2939
  {t="A", q=1240, name="The Troll Witchdoctor", z=15, x=35.21, y=30.66, target={kind="npc", id=4791, name="Nazeer Bloodpike"}, note="For Kin'weelay at Grom'gol, in the Stranglethorn Vale & Swamp of Sorrows guide", section="Dustwallow Marsh & Desolace (36-37)", zoneName="Dustwallow Marsh", p=1074, place="Brackenwall Village", was=2858}, -- 2940
  {t="T", q=1273, name="Questioning Reethe", z=15, x=36.42, y=31.88, target={kind="npc", id=4926, name="Krog"}, note="Krog", section="Dustwallow Marsh & Desolace (36-37)", zoneName="Dustwallow Marsh", p=1074, place="Brackenwall Village", was=2859}, -- 2941
  {t="G", text="Drywallow Crocolisks", z=15, x=44.5, y=24.8, tip="Desolace's last quests are 36-39. Still below 36 after Brackenwall's hand-ins? The Drywallow Crocolisks (35-36) along the river east of the village are the closest at your level: kill them until level 36.", lvlBelow=36.0, section="Dustwallow Marsh & Desolace (36-37)", zoneName="Dustwallow Marsh", p=1075, place="Level 36"}, -- 2942
  {t="N", text="Reach level 36", note="grind on Drywallow Crocolisk", lvlBelow=36.0, section="Dustwallow Marsh & Desolace (36-37)", p=1075, place="Level 36"}, -- 2943
  {t="G", text="Brackenwall Village flight master", z=17, x=35.6, y=31.8, section="Dustwallow Marsh & Desolace (36-37)", zoneName="The Barrens", p=1076, place="Fly to Ratchet"}, -- 2944
  {t="F", text="Ratchet", section="Dustwallow Marsh & Desolace (36-37)", p=1076, place="Fly to Ratchet"}, -- 2945
