  {t="F", text="Orgrimmar", classes={"Druid"}, section="Dustwallow Marsh & Desolace (36-37)", p=1098, place="Back to Orgrimmar"}, -- 2991
  {t="T", q=1184, name="Parts of the Swarm", z=1637, x=75.23, y=34.24, target={kind="npc", id=4485, name="Belgrom Rockmaul"}, note="Belgrom Rockmaul", tip="Belgrom Rockmaul stands in the Valley of Honor.", section="Dustwallow Marsh & Desolace (36-37)", zoneName="Orgrimmar", p=1099, place="Belgrom Rockmaul", was=2903}, -- 2992
  {t="T", q=2841, name="Rig Wars", z=1637, x=75.99, y=25.41, target={kind="npc", id=3412, name="Nogg"}, note="Nogg", tip="Nogg's workshop is in the Valley of Honor beside Belgrom: hand in Rig Wars if you ran Gnomeregan.", ready=2841, section="Dustwallow Marsh & Desolace (36-37)", zoneName="Orgrimmar", p=1100, place="Nogg", was=2904}, -- 2993
  {t="TR", text="Train at your class trainer", tip="Train while you are in the city; everyone else trains in the Undercity, next.", classes={"Hunter", "Shaman"}, section="Dustwallow Marsh & Desolace (36-37)", p=1101, place="Orgrimmar trainers"}, -- 2994
  {t="N", text="The next guide takes the Undercity zeppelin from the tower outside the main gate.", classes={"Hunter", "Shaman"}, section="Dustwallow Marsh & Desolace (36-37)", p=1101, place="Orgrimmar trainers"}, -- 2995
  {t="G", text="Zeppelin to Undercity", z=14, x=50.8, y=13.5, notInZone="Undercity", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Durotar", p=1102, place="Zeppelin to Undercity"}, -- 2996
  {t="TR", text="Train at your class trainer", tip="Train while you are in the Undercity: the trainers stand in the War Quarter, the Rogues' Quarter and the Magic Quarter (Paladins: Garen Largo).", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Alterac Mountains & Arathi Highlands (37-39)", p=1103, place="Undercity trainers"}, -- 2997
  {t="T", q=97985, name="Thundering Hearts", foreverOnly=true, z=1497, x=49.11, y=70.14, target={kind="npc", id=270038, name="Calder Gray"}, note="Calder Gray: Stormheart's heart from Thousand Needles", tip="Calder Gray stands in the Apothecarium.", onQuest={97985}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Undercity", p=1104, place="Calder Gray", was=2909}, -- 2998
  {t="A", q=1164, name="To Steal From Thieves", z=1497, x=63.83, y=49.45, target={kind="npc", id=4486, name="Genavie Callow"}, note="Genavie Callow, beside the flight master", tip="Warriors, Paladins, Rogues, Priests, Mages and Warlocks (not Hunters, Shamans or Druids): Genavie Callow stands beside the flight master. The Dabyrie family's farm lies on the road east through Arathi later in this guide, and your level 40 training brings you back to this flight master from Kargath: she takes the heads then.", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Undercity", p=1105, place="Fly to Tarren Mill"}, -- 2999
