  {t="T", q=503, name="Gol'dir", z=36, x=59.96, y=43.74, target={kind="npc", id=2316, name="Gol'dir"}, note="Gol'dir, on the top floor", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1115, place="Gol'dir", was=2940}, -- 3030
  {t="A", q=506, name="Blackmoore's Legacy", z=36, x=59.96, y=43.74, target={kind="npc", id=2316, name="Gol'dir"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1115, place="Gol'dir", was=2941}, -- 3031
  {t="N", text="Krusk will offer Lord Aliden Perenolde (41, in his manor far up Lordamere Lake) for this: leave it, he is over your level.", section="Alterac Mountains & Arathi Highlands (37-39)", p=1115, place="Gol'dir"}, -- 3032
  {t="C", q=545, obj=2, name="Dalaran Patrols", gv="Kill", gw="Elemental Slave", z=36, x=22.4, y=58.6, note="Kill Elemental Slave", tip="From Strahnbrad follow the road south-west to Gallows' Corner and on west to the ruins north of the Dalaran crater, along the lake shore. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves. Careful: Arcane Sentries (55, elite) and Kirin Tor Guards (55) guard the dome itself and attack the Horde: work the ruins' outer edge and don't go up to the dome.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1116, place="Old Dalaran Ruins: kill these as you meet them", was=2943}, -- 3033
  {t="C", q=557, obj=1, name="Bracers of Binding", gv="Collect", gw="Bracers of Earth Binding", z=36, x=21.6, y=61.9, note="Collect Bracers of Earth Binding", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1116, place="Old Dalaran Ruins: kill these as you meet them", was=2944}, -- 3034
  {t="C", q=545, obj=1, name="Dalaran Patrols", gv="Kill", gw="Dalaran Summoner", z=36, x=22.0, y=57.9, note="Kill Dalaran Summoner", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1116, place="Old Dalaran Ruins: kill these as you meet them", was=2945}, -- 3035
  {t="G", text="Tarren Mill", z=267, x=61.5, y=20.9, tip="Hearth back to Tarren Mill (your hearthstone is bound there), or walk back south-east along the road out of Alterac.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Hillsbrad Foothills", p=1117, place="Back to Tarren Mill"}, -- 3036
  {t="T", q=506, name="Blackmoore's Legacy", z=267, x=63.24, y=20.66, target={kind="npc", id=2229, name="Krusk"}, note="Krusk, inside", tip="Hearth back to Tarren Mill: your hearthstone is bound there.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Hillsbrad Foothills", p=1118, place="Tarren Mill", was=2947}, -- 3037
  {t="T", q=557, name="Bracers of Binding", z=267, x=61.5, y=20.93, target={kind="npc", id=2437, name="Keeper Bel'varil"}, note="Keeper Bel'varil, inside", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Hillsbrad Foothills", p=1118, place="Tarren Mill", was=2948}, -- 3038
  {t="T", q=545, name="Dalaran Patrols", z=267, x=61.6, y=20.85, target={kind="npc", id=2410, name="Magus Wordeen Voidglare"}, note="Magus Wordeen Voidglare, inside", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Hillsbrad Foothills", p=1118, place="Tarren Mill", was=2949}, -- 3039
  {t="N", text="The magus offers a dungeon errand next: leave it.", section="Alterac Mountains & Arathi Highlands (37-39)", p=1118, place="Tarren Mill"}, -- 3040
  {t="G", text="The road east through Thoradin's Wall", z=45, x=32.6, y=40.4, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1119, place="Thoradin's Wall"}, -- 3041
  {t="C", q=676, obj=1, name="The Hammer May Fall", gv="Kill", gw="Boulderfist Ogre", z=45, x=33.15, y=40.79, note="Kill Boulderfist Ogre", tip="Head east out of Tarren Mill through Thoradin's Wall and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south of Northfold Manor; the Enforcers stay in the cave there.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1120, place="Boulderfist camp", was=2952}, -- 3042
  {t="C", q=676, obj=2, name="The Hammer May Fall", z=45, x=32.82, y=43.14, note="Below ground", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1120, place="Boulderfist camp", was=2953}, -- 3043
  {t="C", q=1164, obj=2, name="To Steal From Thieves", z=45, x=54.2, y=38.1, note="Marcel's Head, from Marcel Dabyrie", tip="On along the road east: the Dabyrie farm lies just north of it. Marcel (34) and Fardel (33) Dabyrie walk the farm's western yard among their Laborers and Militia (30-32); Kenata (35) stands at the farm's north-eastern edge.", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1121, place="Dabyrie's Farmstead"}, -- 3044
  {t="C", q=1164, obj=3, name="To Steal From Thieves", z=45, x=54.8, y=38.2, note="Fardel's Head, from Fardel Dabyrie", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1121, place="Dabyrie's Farmstead"}, -- 3045
  {t="C", q=1164, obj=1, name="To Steal From Thieves", z=45, x=56.4, y=36.1, note="Kenata's Head, from Kenata Dabyrie", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1121, place="Dabyrie's Farmstead"}, -- 3046
  {t="T", q=635, name="Crystal in the Mountains", optional=true, z=45, x=62.5, y=33.73, target={kind="object", id=138492, name="Shards of Myzrael"}, tip="Follow the road east. The violet shards glow just off the road a short way west of Hammerfall.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1122, place="The Shards of Myzrael", was=2954}, -- 3047
  {t="A", q=642, name="The Princess Trapped", z=45, x=62.5, y=33.73, target={kind="object", id=138492, name="Shards of Myzrael"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1122, place="The Shards of Myzrael", was=2955}, -- 3048
  {t="A", q=655, name="Hammerfall", z=45, x=72.64, y=33.93, target={kind="npc", id=2792, name="Gor'mul"}, note="Gor'mul, by the gate", tip="Rutherford Twing offers the Defiler's Basic Care Package only once you are Friendly with the Defilers (Arathi Basin): skip it if he doesn't offer it.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1123, place="Hammerfall", was=2956}, -- 3049
  {t="FP", text="Hammerfall flight path", section="Alterac Mountains & Arathi Highlands (37-39)", p=1123, place="Hammerfall"}, -- 3050
