  {t="T", q=676, name="The Hammer May Fall", z=45, x=74.24, y=33.92, target={kind="npc", id=2771, name="Drum Fel"}, note="Drum Fel", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1123, place="Hammerfall", was=2960}, -- 3053
