  {t="T", q=655, name="Hammerfall", z=45, x=74.72, y=36.29, target={kind="npc", id=2706, name="Tor'gan"}, note="Tor'gan", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1123, place="Hammerfall", was=2962}, -- 3055
  {t="A", q=672, name="Raising Spirits", z=45, x=74.72, y=36.29, target={kind="npc", id=2706, name="Tor'gan"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1123, place="Hammerfall", was=2963}, -- 3056
  {t="A", q=97539, name="Silky Sutures", foreverOnly=true, z=45, x=73.41, y=36.89, target={kind="npc", id=12920, name="Doctor Gregory Victor"}, note="Doctor Gregory Victor, at the south gate. If Doctor Gregory Victor offers nothing, another player may be running his First Aid quest Triage: he can be busy for a few minutes. Wait, then talk to him again.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1123, place="Hammerfall", was=2964}, -- 3057
  {t="A", q=639, name="Sigil of Strom", group=true, z=45, x=73.8, y=33.96, target={kind="npc", id=2703, name="Zengu"}, note="Zengu", tip="Zengu's Sigil of Strom drops from the elite Syndicate (35-38) in Stromgarde's ruins, the west of the highlands. Great XP if you have a group for it: the route passes Stromgarde on its way to the inner circle.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1124, place="Stromgarde quests for a group", was=2965}, -- 3058
  {t="C", q=642, name="The Princess Trapped", gv="Collect", gw="Mote of Myzrael", z=45, x=77.49, y=34.88, note="Collect Mote of Myzrael", tip="Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1125, place="Drywhisker Gorge", was=2966}, -- 3059
  {t="T", q=642, name="The Princess Trapped", z=45, x=84.31, y=30.95, target={kind="object", id=2701, name="Iridescent Shards"}, note="Below ground", tip="The Iridescent Shards lie at the far end of the gorge.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1126, place="Iridescent Shards", was=2967}, -- 3060
  {t="A", q=651, name="Stones of Binding", z=45, x=84.31, y=30.95, target={kind="object", id=2701, name="Iridescent Shards"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1126, place="Iridescent Shards", was=2968}, -- 3061
  {t="C", q=651, name="Stones of Binding", z=45, x=66.7, y=29.72, note="Cresting Key", tip="Careful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1127, place="The Stone of East Binding", was=2969}, -- 3062
  {t="C", q=677, obj=2, name="Call to Arms", gv="Kill", gw="Witherbark Headhunter", z=45, x=71.88, y=63.02, note="Kill Witherbark Headhunter", tip="South of Hammerfall, the Witherbark trolls hold the village in the hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village. Careful: All three troll types flee for help at 15% health, which can pull more trolls from the nearby camps.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1128, place="Witherbark Village", was=2970}, -- 3063
  {t="C", q=677, obj=1, name="Call to Arms", gv="Kill", gw="Witherbark Axe Thrower", z=45, x=70.87, y=61.66, note="Kill Witherbark Axe Thrower", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1128, place="Witherbark Village", was=2971}, -- 3064
  {t="C", q=677, obj=3, name="Call to Arms", gv="Kill", gw="Witherbark Witch Doctor", z=45, x=71.6, y=61.84, note="Kill Witherbark Witch Doctor", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1128, place="Witherbark Village", was=2972}, -- 3065
  {t="C", q=672, name="Raising Spirits", gv="Collect", gw="Highland Raptor Eye", z=45, x=67.1, y=56.28, note="Collect Highland Raptor Eye", tip="On the way back north, Highland Striders roam the hills all around Hammerfall and drop the eyes, and south of it the Plains Creepers (32-33) spin their webs in the grass; they carry the spidersilk.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1129, place="Highland raptors and Plains Creepers", was=2973}, -- 3066
  {t="C", q=97539, name="Silky Sutures", foreverOnly=true, z=45, x=69.5, y=50.5, note="Surgical Spidersilk, from Plains Creepers", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1129, place="Highland raptors and Plains Creepers", was=2974}, -- 3067
