  {t="A", q=709, name="Solution to Doom", group=true, z=3, x=51.22, y=76.78, target={kind="npc", id=2785, name="Theldurin the Lost"}, tip="Theldurin sits among the dwarven ruins at Agmond's End, just east of the elementals. His tablet lies just inside Uldaman's cave mouth, beside level 38 elites: a quest for a group.", section="Badlands (38-39)", zoneName="Badlands", p=1158, place="Agmond's End", was=3052}, -- 3158
  {t="C", q=1108, name="Indurium", gv="Collect", gw="Indurium Flake", z=3, x=51.18, y=71.65, note="Collect Indurium Flake", tip="The Stonevault troggs dig around the cave mouths south of the Valley of Fangs, on the way north from Agmond's End; the Bonesnappers and Shamans drop the flakes. The Buzzards for Rigglefuzz's wings circle the hills between the Valley of Fangs and Agmond's End.", section="Badlands (38-39)", zoneName="Badlands", p=1159, place="Stonevault troggs", was=3053}, -- 3159
  {t="C", q=703, name="Barbecued Buzzard Wings", gv="Collect", gw="Buzzard Wing", z=3, x=50.13, y=77.87, note="Collect Buzzard Wing", section="Badlands (38-39)", zoneName="Badlands", p=1159, place="Stonevault troggs", was=3054}, -- 3160
  {t="T", q=703, name="Barbecued Buzzard Wings", z=3, x=42.39, y=52.93, target={kind="npc", id=2817, name="Rigglefuzz"}, note="Rigglefuzz", tip="The road north to Uldaman runs through the Valley of Fangs: Rigglefuzz and Martek take the wings and the flakes on the way.", section="Badlands (38-39)", zoneName="Badlands", p=1160, place="Valley of Fangs", was=3055}, -- 3161
