  {t="C", q=709, name="Solution to Doom", group=true, z=3, x=39.34, y=18.82, note="Below ground", tip="Keep north on the road to Uldaman's entrance, in the north of the Badlands: the chest lies just inside the cave mouth. Magregan Deepshadow and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together.", section="Badlands (38-39)", zoneName="Badlands", p=1161, place="Ancient Chest", was=3058}, -- 3164
  {t="T", q=709, name="Solution to Doom", group=true, z=3, x=51.22, y=76.78, target={kind="npc", id=2785, name="Theldurin the Lost"}, note="Theldurin the Lost", tip="Head back south down the road, past the Valley of Fangs.", section="Badlands (38-39)", zoneName="Badlands", p=1162, place="Agmond's End", was=3059}, -- 3165
  {t="A", q=728, name="To the Undercity for Yagyin's Digest", group=true, z=3, x=51.22, y=76.78, target={kind="npc", id=2785, name="Theldurin the Lost"}, section="Badlands (38-39)", zoneName="Badlands", p=1162, place="Agmond's End", was=3060}, -- 3166
  {t="T", q=711, name="Study of the Elements: Rock", z=3, x=25.95, y=44.87, target={kind="npc", id=2921, name="Lotwil Veriatus"}, note="Lotwil Veriatus", tip="North-west across the basin to Lotwil's camp. Short of Jarkal's shards? The Lesser Rock Elementals (37) on the flats west of the camp drop them about one kill in five.", section="Badlands (38-39)", zoneName="Badlands", p=1163, place="The Dustbowl", was=3061}, -- 3167
  {t="N", text="Lotwil's next study wants bracers from the Greater Rock Elementals (42-44) in the south-western gulches, well above you: leave it.", section="Badlands (38-39)", p=1163, place="The Dustbowl"}, -- 3168
