  {t="C", q=600, obj=1, name="Venture Company Mining", gv="Collect", gw="Singing Blue Crystal", z=33, x=42.02, y=46.3, note="Collect Singing Blue Crystal", tip="Careful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp.", section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Stranglethorn Vale", p=1183, place="Venture Co. mine", was=3105}, -- 3223
  {t="C", q=192, name="Panther Mastery", gv="Kill", gw="Shadowmaw Panther", z=33, x=41.3, y=34.8, note="Kill Shadowmaw Panther", tip="Panther Mastery is still open: the Shadowmaw Panthers (37-38) stalk the jungle north of the mine, towards the Mosh'Ogg hills. They use Sneak, so they show only when you are close: pull them one at a time, and leave the Elder Shadowmaw Panthers (42-43) alone.", onQuest={192}, section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Stranglethorn Vale", p=1184, place="Shadowmaw Panthers"}, -- 3224
