  {t="C", q=188, name="Tiger Mastery", gv="Collect", gw="Paw of Sin'Dall", z=33, x=31.8, y=16.4, note="Collect Paw of Sin'Dall", tip="Sin'Dall, the tiger Ajeck sent you after on your last visit, prowls the hilltop just south-west of the camp.", onQuest={188}, section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Stranglethorn Vale", p=1189, place="Sin'Dall"}, -- 3233
