  {t="A", q=338, name="The Green Hills of Stranglethorn", optional=true, z=33, x=35.66, y=10.53, target={kind="npc", id=716, name="Barnil Stonepot"}, note="Barnil Stonepot", tip="Barnil Stonepot collects the pages of The Green Hills of Stranglethorn: the trolls of the vale drop them now and then. Take his quest; each chapter he takes once you have all its pages.", turnedIn={583}, section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Stranglethorn Vale", p=1193, place="The Green Hills of Stranglethorn", was=3116}, -- 3238
