  {t="C", q=584, obj=1, name="Bloodscalp Clan Heads", gv="Collect", gw="Gan'zulah's Head", z=33, x=23.44, y=8.12, note="Collect Gan'zulah's Head", tip="On the coast between Zul'Kunda and Grom'gol an Elder Saltwater Crocolisk (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for Drizzlik.", section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Stranglethorn Vale", p=1199, place="Zul'Kunda", was=3126}, -- 3248
  {t="C", q=95748, obj=1, name="The Gurubashi Legends of Old", foreverOnly=true, z=33, x=23.0, y=12.0, note="from the Fall of Gurubashi, in the ruins", section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Stranglethorn Vale", p=1199, place="Zul'Kunda", was=3127}, -- 3249
