  {t="C", q=699, obj=1, name="Lack of Surplus", gv="Collect", gw="Sawtooth Snapper Claw", z=8, x=83.8, y=95.42, note="Collect Sawtooth Snapper Claw", tip="Careful: a Methuselah Crab (level 60) walks the south-east strand: give it a wide berth.", section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Swamp of Sorrows", p=1243, place="Sawtooth snappers", was=3713}, -- 3331
