  {t="T", q=1422, name="Threat From the Sea", z=8, x=83.76, y=80.41, target={kind="npc", id=5593, name="Katar"}, note="Katar", section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Swamp of Sorrows", p=1244, place="Misty Reed Post", was=3717}, -- 3334
  {t="A", q=1426, name="Threat From the Sea", z=8, x=83.76, y=80.41, target={kind="npc", id=5593, name="Katar"}, note="Katar: the murlocs (41-44) wait for your next swamp visit", section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Swamp of Sorrows", p=1244, place="Misty Reed Post", was=3718}, -- 3335
  {t="T", q=1424, name="Pool of Tears", z=8, x=47.93, y=54.78, target={kind="npc", id=1443, name="Fel'zerul"}, note="Fel'zerul, on the top floor", tip="Back north-west along the road to Stonard: Fel'zerul, on the top floor, takes the artifacts. Fresh Meat's crawlers and Katar's murlocs wait for your next swamp visit.", section="Stranglethorn Vale & Swamp of Sorrows (39-42)", zoneName="Swamp of Sorrows", p=1245, place="Stonard", was=3730}, -- 3336
  {t="G", text="Stonard flight master", z=3, x=46.1, y=54.7, tip="The Riverglades lie south of the Badlands. Fly from Stonard to Kargath: the way down into the zone starts there.", inZone="Swamp of Sorrows", taxi="Kargath", section="Riverglades (41-44)", zoneName="Badlands", p=1246, place="Fly to Kargath"}, -- 3337
  {t="F", text="Kargath", inZone="Swamp of Sorrows", taxi="Kargath", section="Riverglades (41-44)", p=1246, place="Fly to Kargath"}, -- 3338
  {t="G", text="Into the Riverglades", z=16591, x=55.0, y=93.0, tip="From Kargath, ride south-east across the Badlands to the zone's southern edge: the pass of Twilight's Shroud leads down into the Riverglades. Rog'mar, the Horde's fort, stands in the middle of the zone, east along the valley.", notInZone="Riverglades", taxi="Kargath", section="Riverglades (41-44)", zoneName="Riverglades", p=1247, place="Into the Riverglades"}, -- 3339
  {t="G", text="Riverglades", z=16591, x=32.0, y=29.9, notInZone="Riverglades", taxi="Kargath", section="Riverglades (41-44)", zoneName="Riverglades", p=1247, place="Into the Riverglades"}, -- 3340
  {t="F", text="Freewind Post", tip="The Riverglades lie across the sea from Tanaris: a goblin boat sails from Steamwheedle Port, north-east of Gadgetzan, to Powderfuse Port. Fly to Freewind Post in Thousand Needles and head south-east through the Shimmering Flats to Gadgetzan. (If you already know Kargath in the Badlands, the way in through Twilight's Shroud works too.)", notInZone="Riverglades", notTaxi="Kargath", section="Riverglades (41-44)", p=1248, place="Fly to Freewind Post"}, -- 3341
  {t="FP", text="Gadgetzan flight path", tip="Learn Gadgetzan's flight path: it saves the ride next time.", notInZone="Riverglades", notTaxi="Kargath", section="Riverglades (41-44)", p=1249, place="Gadgetzan"}, -- 3342
  {t="G", text="Boat to Powderfuse Port", z=440, x=67.57, y=23.1, tip="Steamwheedle Port is on the coast north-east of Gadgetzan: wait on the pier for the goblin boat to Powderfuse Port.", notInZone="Riverglades", notTaxi="Kargath", section="Riverglades (41-44)", zoneName="Tanaris", p=1250, place="Boat to Powderfuse Port"}, -- 3343
  {t="A", q=95062, name="Frazzlespark's Crate", foreverOnly=true, z=16591, x=77.1, y=52.9, target={kind="npc", id=255897, name="Friz Frazzlespark"}, note="Frazzlespark's Crate: for Krom'rosh in Rog'mar", tip="Friz Frazzlespark keeps a stall at the west end of the docks. The port's other jobs are for later in this guide: this crate goes to the Horde's fort.", notTaxi="Kargath", section="Riverglades (41-44)", zoneName="Riverglades", p=1251, place="Powderfuse Port", was=3211}, -- 3344
  {t="A", q=96063, name="Gaseous Gold", foreverOnly=true, z=16591, x=68.15, y=48.57, target={kind="npc", id=263367, name="Sleebo Fizzlespout"}, note="Gaseous Gold", tip="West up the road from the port: Sleebo Fizzlespout has his workshop on the hill. The gas vents are in the marsh south-west of it, on your first hunt for Neza.", notTaxi="Kargath", section="Riverglades (41-44)", zoneName="Riverglades", p=1252, place="Sleebo's workshop", was=3212}, -- 3345
  {t="A", q=96107, name="Feathers for Fletching", foreverOnly=true, z=16591, x=60.46, y=47.86, target={kind="npc", id=258031, name="Neza Bloodsnout"}, note="Neza Bloodsnout: Feathers for Fletching", tip="West to Rog'mar, the Horde's fort in the middle of the zone. Neza Bloodsnout stands on its east side, Kreza Darkthorn and Krom'rosh in the middle with Grakna, the wind rider master; Innkeeper Toka and Tan'jani on the west side.", section="Riverglades (41-44)", zoneName="Riverglades", p=1253, place="Rog'mar", was=3213}, -- 3346
  {t="A", q=93788, name="Borrowed Blades", foreverOnly=true, z=16591, x=59.92, y=45.97, target={kind="npc", id=256657, name="Kreza Darkthorn"}, note="Kreza Darkthorn: Borrowed Blades", section="Riverglades (41-44)", zoneName="Riverglades", p=1253, place="Rog'mar", was=3214}, -- 3347
  {t="T", q=95141, name="Report to Rog'mar", foreverOnly=true, z=16591, x=59.37, y=45.6, target={kind="npc", id=256418, name="Krom'rosh"}, note="Krom'rosh: Aggro'gosh's report from Grom'gol, if you carry it", section="Riverglades (41-44)", zoneName="Riverglades", p=1253, place="Rog'mar", was=3215}, -- 3348
  {t="A", q=93786, name="A Message in Blood", foreverOnly=true, z=16591, x=59.37, y=45.6, target={kind="npc", id=256418, name="Krom'rosh"}, note="A Message in Blood", section="Riverglades (41-44)", zoneName="Riverglades", p=1253, place="Rog'mar", was=3216}, -- 3349
