  {t="FP", text="Rog'mar flight path", z=16591, x=59.59, y=45.08, note="Grakna, in the middle of the fort", section="Riverglades (41-44)", zoneName="Riverglades", p=1253, place="Rog'mar"}, -- 3351
  {t="SH", text="Rog'mar", z=16591, x=57.99, y=45.1, note="Innkeeper Toka", section="Riverglades (41-44)", zoneName="Riverglades", p=1253, place="Rog'mar"}, -- 3352
