  {t="A", q=95033, name="On the Other Side", foreverOnly=true, z=16591, x=58.13, y=45.32, target={kind="npc", id=263190, name="Tan'jani"}, note="Tan'jani: On the Other Side, for Witch Doctor Uzer'i at Camp Mojache in the Feralas guide", section="Riverglades (41-44)", zoneName="Riverglades", p=1253, place="Rog'mar", was=3221}, -- 3354
  {t="T", q=95062, name="Frazzlespark's Crate", foreverOnly=true, z=16591, x=59.37, y=45.6, target={kind="npc", id=256418, name="Krom'rosh"}, note="Krom'rosh", tip="Frazzlespark's crate from the port goes to Krom'rosh, in the middle of the fort.", onQuest={95062}, section="Riverglades (41-44)", zoneName="Riverglades", p=1254, place="Krom'rosh", was=3222}, -- 3355
  {t="A", q=96063, name="Gaseous Gold", foreverOnly=true, z=16591, x=68.15, y=48.57, target={kind="npc", id=263367, name="Sleebo Fizzlespout"}, note="Gaseous Gold", tip="East of Rog'mar, on the hill above the road to Powderfuse Port: Sleebo Fizzlespout has his workshop there. The gas vents are in the marsh south-west of it, on your first hunt for Neza.", available={96063}, section="Riverglades (41-44)", zoneName="Riverglades", p=1255, place="Sleebo's workshop", was=3223}, -- 3356
  {t="C", q=96107, obj=1, name="Feathers for Fletching", foreverOnly=true, z=16591, x=68.21, y=48.79, note="Plains Buzzard Feather", tip="South-east of Rog'mar the plains run down to Terral's Watch. The Low Plains Buzzards circle everywhere; a picked carcass lies in the grass (its skull starts A Feast for Buzzards), and the marsh vents are just past it.", section="Riverglades (41-44)", zoneName="Riverglades", p=1256, place="The plains and the marsh", was=3224}, -- 3357
  {t="A", q=96103, name="A Feast for Buzzards", foreverOnly=true, z=16591, x=61.64, y=58.82, target={kind="npc", id=263316, name="Picked Carcass"}, note="Picked Carcass: A Feast for Buzzards", section="Riverglades (41-44)", zoneName="Riverglades", p=1256, place="The plains and the marsh", was=3225}, -- 3358
