  {t="A", q=96105, name="King of the Wild Plains", group=true, foreverOnly=true, z=16591, x=60.46, y=47.86, target={kind="npc", id=258031, name="Neza Bloodsnout"}, note="Neza Bloodsnout", tip="Ombassa, an elite lion (level 41), prowls the plains south of Rog'mar, where the lions are: grouping up is advised.", section="Riverglades (41-44)", zoneName="Riverglades", p=1261, place="King of the Wild Plains", was=3240}, -- 3373
  {t="C", q=96109, obj=1, name="A Hunter's Quiver", foreverOnly=true, z=16591, x=60.52, y=47.84, note="Prized Lion Hide", tip="Careful: Ombassa, an elite lion (level 41), prowls the same plains around 59.6,53.2: keep an eye out for him and pull the lions away from where he walks.", section="Riverglades (41-44)", zoneName="Riverglades", p=1262, place="The lions", was=3241}, -- 3374
