  {t="A", q=94533, name="Snargl's Snout", group=true, foreverOnly=true, z=16591, x=60.46, y=47.86, target={kind="npc", id=258031, name="Neza Bloodsnout"}, note="Neza Bloodsnout", tip="Snargl is an elite gnoll (level 40) who roams the south-western camps of the Bristle Hills: grouping up is advised.", section="Riverglades (41-44)", zoneName="Riverglades", p=1266, place="Snargl's Snout", was=3246}, -- 3379
  {t="A", q=94535, name="Bristle Hills Bandits", foreverOnly=true, z=16591, x=59.92, y=45.97, target={kind="npc", id=256657, name="Kreza Darkthorn"}, note="Bristle Hills Bandits", section="Riverglades (41-44)", zoneName="Riverglades", p=1267, place="Kreza Darkthorn", was=3247}, -- 3380
  {t="C", q=93788, obj=1, name="Borrowed Blades", foreverOnly=true, z=16591, x=43.82, y=57.36, note="Woodworker's Axe", tip="South-west across the river to the Alliance lumber camp. The lumberjacks carry the axes. Loot Wood Bundles from the Peasant Woodpiles around the camp and use them to fletch Makeshift Stickin' Spears. Ghostmaw, an elite (level 42), prowls the river by the camp: if he comes your way, back off and let him pass.", section="Riverglades (41-44)", zoneName="Riverglades", p=1268, place="Turner's Logging Camp", was=3248}, -- 3381
  {t="N", text="Collect Wood Bundle", z=16591, x=39.2, y=62.8, note="Wood Bundle, from the Peasant Woodpiles", section="Riverglades (41-44)", zoneName="Riverglades", p=1268, place="Turner's Logging Camp"}, -- 3382
