  {t="A", q=95934, name="Proof of Profit", foreverOnly=true, z=16591, x=30.21, y=69.07, target={kind="npc", id=262399, name="Gelinda Coppergleam"}, note="Proof of Profit", section="Riverglades (41-44)", zoneName="Riverglades", p=1271, place="Gelinda Coppergleam", was=3257}, -- 3390
  {t="C", q=95792, obj=1, name="Clear 'em Out", foreverOnly=true, z=16591, x=30.0, y=72.2, note="Cinderscale Whelp", tip="The whelps nest all over the hollow; the warriors guard its back, by the Cubic Draconia. The warriors are level 41-42: pull them one at a time. Scaldaron, a rare elite drake, can be up here too: leave him be unless you have a group.", section="Riverglades (41-44)", zoneName="Riverglades", p=1272, place="The Cinderscale hollow", was=3258}, -- 3391
