  {t="T", q=95162, name="Paletusk Harvesting", foreverOnly=true, z=16591, x=70.73, y=28.09, target={kind="npc", id=256728, name="Na'zok"}, section="Riverglades (41-44)", zoneName="Riverglades", p=1302, place="Na'zok", was=3334}, -- 3467
  {t="A", q=94556, name="Jom-jom's Escape", foreverOnly=true, z=16591, x=73.4, y=24.7, target={kind="npc", id=258048, name="Jom-jom"}, note="Jom-jom, in the cave", tip="Jom-jom waits at the back of the cave by the Twilight ogres' camp north-east of Na'zok: go all the way in to find him, then take him home to Bolder'ok and keep the cultists off him. If he falls, take the quest from him again.", section="Riverglades (41-44)", zoneName="Riverglades", p=1303, place="Jom-jom's Escape", was=3335}, -- 3468
  {t="C", q=94556, name="Jom-jom's Escape", foreverOnly=true, z=16591, x=64.4, y=15.6, note="help Jom-jom reach Bolder'ok", section="Riverglades (41-44)", zoneName="Riverglades", p=1303, place="Jom-jom's Escape", was=3336}, -- 3469
  {t="T", q=94556, name="Jom-jom's Escape", foreverOnly=true, z=16591, x=64.25, y=15.72, target={kind="npc", id=255829, name="Clugfist"}, note="Clugfist", tip="Back to Clugfist on his hill. Jezap Jinglesprocket runs the Bloodmaster's Ring just below it.", section="Riverglades (41-44)", zoneName="Riverglades", p=1304, place="Bolder'ok", was=3337}, -- 3470
