  {t="T", q=94668, name="Bloodmaster's Ring", foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, note="Jezap Jinglesprocket", turnedIn={95420}, section="Riverglades (41-44)", zoneName="Riverglades", p=1305, place="Clugfist", was=3342}, -- 3475
  {t="A", q=94669, name="Pay to Play", optional=true, foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, note="Pay to Play: the Ring's bouts, one-on-one fights with elites (41-45); a deposit first", turnedIn={95420}, section="Riverglades (41-44)", zoneName="Riverglades", p=1305, place="Clugfist", was=3343}, -- 3476
  {t="T", q=94669, name="Pay to Play", foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, note="Jezap Jinglesprocket", tip="Each bout is a fight in the ring below Clugfist's hill against an elite: Buzzbeak (41), Kronk and Bonegnaw (42), Mog'thar (43), Snufflesnout (44) and Chub'chob (45). Come in rested, with full health and mana; if a bout goes wrong, Jezap offers it again.", onQuest={94669}, section="Riverglades (41-44)", zoneName="Riverglades", p=1306, place="The Bloodmaster's Ring: Buzzbeak", was=3344}, -- 3477
  {t="A", q=94670, name="Bloodmaster's Ring", optional=true, foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, note="Bloodmaster's Ring: Buzzbeak", onQuest={94669}, section="Riverglades (41-44)", zoneName="Riverglades", p=1306, place="The Bloodmaster's Ring: Buzzbeak", was=3345}, -- 3478
  {t="C", q=94670, name="Bloodmaster's Ring", foreverOnly=true, z=16591, x=65.7, y=20.2, note="beat Buzzbeak", onQuest={94669}, section="Riverglades (41-44)", zoneName="Riverglades", p=1306, place="The Bloodmaster's Ring: Buzzbeak", was=3346}, -- 3479
  {t="T", q=94670, name="Bloodmaster's Ring", foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, onQuest={94669}, section="Riverglades (41-44)", zoneName="Riverglades", p=1306, place="The Bloodmaster's Ring: Buzzbeak", was=3347}, -- 3480
