  {t="T", q=94962, name="Bloodmaster's Ring", foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, turnedIn={94670}, section="Riverglades (41-44)", zoneName="Riverglades", p=1307, place="The Bloodmaster's Ring: Kronk and Bonegnaw", was=3353}, -- 3486
  {t="A", q=94964, name="Bloodmaster's Ring", group=true, foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, note="Mog'thar (43)", tip="Mog'thar is a level 43 elite, at or above your level here: a hard one-on-one fight in the ring, where nobody can help you. Take it only rested, with full health and mana; Gobam's and Hamur's errands and the last two bouts come after him.", turnedIn={94962}, section="Riverglades (41-44)", zoneName="Riverglades", p=1308, place="The Bloodmaster's Ring: Mog'thar", was=3354}, -- 3487
  {t="C", q=94964, name="Bloodmaster's Ring", group=true, foreverOnly=true, z=16591, x=65.7, y=20.2, turnedIn={94962}, section="Riverglades (41-44)", zoneName="Riverglades", p=1308, place="The Bloodmaster's Ring: Mog'thar", was=3355}, -- 3488
  {t="T", q=94964, name="Bloodmaster's Ring", group=true, foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, turnedIn={94962}, section="Riverglades (41-44)", zoneName="Riverglades", p=1308, place="The Bloodmaster's Ring: Mog'thar", was=3356}, -- 3489
  {t="A", q=94733, name="Our Ogre Friend", foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, note="Jezap Jinglesprocket: Our Ogre Friend", tip="With Mog'thar beaten, Jezap sends you to Gobam, who keeps the Ring's beasts a few steps north-east of the ring; Hamur, just south of the ring, wants good rock. Gobam's boar treat needs Sweetberries from the pirates' slopes north of Powderfuse Port and Riverweed from the river between Rog'mar and Bolder'ok: this guide gathers both and brings you back here after the port, for the Ring's last two bouts.", turnedIn={94964}, section="Riverglades (41-44)", zoneName="Riverglades", p=1309, place="Gobam and Hamur"}, -- 3490
  {t="T", q=94733, name="Our Ogre Friend", foreverOnly=true, z=16591, x=67, y=17.18, target={kind="npc", id=257058, name="Gobam"}, note="Gobam", turnedIn={94964}, section="Riverglades (41-44)", zoneName="Riverglades", p=1309, place="Gobam and Hamur"}, -- 3491
  {t="A", q=94734, name="A Boar's Delight", foreverOnly=true, z=16591, x=67, y=17.18, target={kind="npc", id=257058, name="Gobam"}, note="A Boar's Delight", turnedIn={94964}, section="Riverglades (41-44)", zoneName="Riverglades", p=1309, place="Gobam and Hamur"}, -- 3492
  {t="A", q=95183, name="Step One: Rock", foreverOnly=true, z=16591, x=69.65, y=25.93, target={kind="npc", id=259988, name="Gorgegut"}, note="Hamur: Step One: Rock", turnedIn={94964}, section="Riverglades (41-44)", zoneName="Riverglades", p=1309, place="Gobam and Hamur"}, -- 3493
  {t="C", q=95183, obj=1, name="Step One: Rock", foreverOnly=true, z=16591, x=66.4, y=25.5, note="Good Rock", tip="South-east from Bolder'ok on the way down to the port: Hamur's rock piles lie in the hills just south of the town and on the slopes west of the Twilight ogres' camp.", onQuest={95183}, section="Riverglades (41-44)", zoneName="Riverglades", p=1310, place="The rock piles"}, -- 3494
  {t="T", q=93976, name="The Goblin Trader", foreverOnly=true, z=16591, x=77.1, y=52.9, target={kind="npc", id=255897, name="Friz Frazzlespark"}, note="Friz Frazzlespark: The Goblin Trader", tip="South-east down out of the hills to Powderfuse Port, the goblins' harbour on the coast. Friz Frazzlespark keeps a stall at the west end of the docks, Fimbo Greasemitz cooks by the inn, and Wharfmaster Whizzbuzz works the north pier.", section="Riverglades (41-44)", zoneName="Riverglades", p=1311, place="Powderfuse Port", was=3363}, -- 3495
  {t="A", q=95288, name="Smuggler's Paradise", foreverOnly=true, z=16591, x=77.1, y=52.9, target={kind="npc", id=255897, name="Friz Frazzlespark"}, note="Smuggler's Paradise", section="Riverglades (41-44)", zoneName="Riverglades", p=1311, place="Powderfuse Port", was=3364}, -- 3496
