  {t="A", q=95118, name="Saltwater Savages", foreverOnly=true, z=16591, x=79.45, y=52.71, target={kind="npc", id=259961, name="Wharfmaster Whizzbuzz"}, note="Wharfmaster Whizzbuzz: Saltwater Savages", section="Riverglades (41-44)", zoneName="Riverglades", p=1311, place="Powderfuse Port", was=3367}, -- 3499
