  {t="T", q=97332, name="Twice Misplaced Trust", foreverOnly=true, z=16591, x=79.45, y=52.71, target={kind="npc", id=259961, name="Wharfmaster Whizzbuzz"}, note="Wharfmaster Whizzbuzz", tip="Wharfmaster Whizzbuzz on the north pier takes Lozgil's Twice Reordered Package.", onQuest={97332}, section="Riverglades (41-44)", zoneName="Riverglades", p=1312, place="Wharfmaster Whizzbuzz", was=3369}, -- 3501
  {t="A", q=95120, name="WANTED: Old Rot-Chum", group=true, foreverOnly=true, z=16591, x=78.49, y=53.94, target={kind="object", id=628948, name="WANTED!"}, note="The WANTED! poster by the inn", tip="Old Rot-Chum is an elite (level 42) on the south shore: grouping up is advised.", section="Riverglades (41-44)", zoneName="Riverglades", p=1313, place="WANTED: Old Rot-Chum", was=3370}, -- 3502
  {t="A", q=95260, name="Terrors From the Deep", foreverOnly=true, z=16591, x=72.36, y=61.9, target={kind="object", id=629761, name="Painted Hide"}, note="Painted Hide: Terrors From the Deep", tip="South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts Terrors From the Deep for Argo Brinewhistle at the docks.", section="Riverglades (41-44)", zoneName="Riverglades", p=1314, place="The murlocs, south-west", was=3371}, -- 3503
