  {t="T", q=95260, name="Terrors From the Deep", foreverOnly=true, z=16591, x=79.95, y=52.49, target={kind="npc", id=260231, name="Argo Brinewhistle"}, note="Argo Brinewhistle", section="Riverglades (41-44)", zoneName="Riverglades", p=1316, place="Back through the port", was=3377}, -- 3509
  {t="A", q=95261, name="It Takes Guts", foreverOnly=true, z=16591, x=79.95, y=52.49, target={kind="npc", id=260231, name="Argo Brinewhistle"}, note="It Takes Guts: the beasts' entrails come as you go; the mushrooms grow on the ridge west of the pirates", section="Riverglades (41-44)", zoneName="Riverglades", p=1316, place="Back through the port", was=3378}, -- 3510
  {t="C", q=95261, obj=1, name="It Takes Guts", optional=true, foreverOnly=true, z=16591, x=80.59, y=52.3, note="Beast Entrails", tip="Careful: Old Rot-Chum (elite, 42) wanders the shore and Ghostmaw (elite, 42) the river: take your beasts away from them.", section="Riverglades (41-44)", zoneName="Riverglades", p=1317, place="Beast Entrails as you go", was=3379}, -- 3511
  {t="C", q=95121, obj=2, name="A Taste of the Sea", foreverOnly=true, z=16591, x=80.59, y=52.3, note="Sand Crawler Meat", tip="North along the beach from the docks: the crawlers drop the meat for Fimbo, and their entrails count for Argo. Trapclaw, a big crab, scuttles along the rocks east of the docks. Gul'gash, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away.", section="Riverglades (41-44)", zoneName="Riverglades", p=1318, place="The crawlers and Trapclaw", was=3380}, -- 3512
  {t="C", q=95254, obj=1, name="WANTED: Trapclaw", foreverOnly=true, z=16591, x=80.7, y=52.39, note="Trapclaw's Pincer", section="Riverglades (41-44)", zoneName="Riverglades", p=1318, place="The crawlers and Trapclaw", was=3381}, -- 3513
  {t="C", q=95119, obj=1, name="Unfriendly Competition", foreverOnly=true, z=16591, x=79.78, y=51.76, note="Eastsea Buccaneer", tip="North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. Gul'gash walks the camp too: keep an eye out for him.", section="Riverglades (41-44)", zoneName="Riverglades", p=1319, place="The Eastsea pirates", was=3382}, -- 3514
