  {t="C", q=95261, obj=2, name="It Takes Guts", foreverOnly=true, z=16591, x=75.6, y=26.07, note="Rotflesh Mushroom", tip="West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too.", section="Riverglades (41-44)", zoneName="Riverglades", p=1327, place="Rotflesh Mushrooms", was=3409}, -- 3542
