  {t="C", q=95267, obj=1, name="The Monster Surfaces", foreverOnly=true, z=16591, x=76.85, y=68.01, note="Sea Monster's Head", tip="The Monstrous Threshadon prowls the shallows south-west of the port, below the murlocs' beaches. Old Rot-Chum, an elite, walks the shore close by: give him room.", onQuest={95267}, section="Riverglades (41-44)", zoneName="Riverglades", p=1330, place="The Monster Surfaces", was=3415}, -- 3548
  {t="T", q=95267, name="The Monster Surfaces", foreverOnly=true, z=16591, x=79.95, y=52.49, target={kind="npc", id=260231, name="Argo Brinewhistle"}, onQuest={95267}, section="Riverglades (41-44)", zoneName="Riverglades", p=1331, place="Argo Brinewhistle", was=3416}, -- 3549
  {t="C", q=94734, obj=2, name="A Boar's Delight", foreverOnly=true, z=16591, x=62.6, y=39.0, note="Riverweed", tip="From the port, ride north-west to the river and follow it upstream towards Bolder'ok: Gobam's Riverweed grows along its banks between Rog'mar and Bolder'ok.", onQuest={94734}, section="Riverglades (41-44)", zoneName="Riverglades", p=1332, place="The river: Riverweed"}, -- 3550
