  {t="A", q=94737, name="A Treat for a Friend", foreverOnly=true, z=16591, x=67, y=17.18, target={kind="npc", id=257058, name="Gobam"}, note="A Treat for a Friend", onQuest={94734}, section="Riverglades (41-44)", zoneName="Riverglades", p=1334, place="Gobam"}, -- 3553
