  {t="A", q=94965, name="Bloodmaster's Ring", group=true, foreverOnly=true, z=16591, x=65.58, y=21.45, target={kind="npc", id=257062, name="Jezap Jinglesprocket"}, note="Snufflesnout (44)", tip="Snufflesnout (44) is elite: a hard one-on-one fight in the ring, where nobody can help you. Come in rested, with full health and mana.", turnedIn={94737}, section="Riverglades (41-44)", zoneName="Riverglades", p=1335, place="The Bloodmaster's Ring: Snufflesnout", was=3357}, -- 3555
