  {t="T", q=95063, name="Bloodmaster's Ring", group=true, foreverOnly=true, z=16591, x=64.25, y=15.72, target={kind="npc", id=255829, name="Clugfist"}, note="Clugfist, on the hill", turnedIn={94965}, section="Riverglades (41-44)", zoneName="Riverglades", p=1336, place="The Bloodmaster's Ring: Chub'chob", was=3362}, -- 3560
  {t="T", q=95428, name="Clugfist's Decree", foreverOnly=true, z=16591, x=59.37, y=45.6, target={kind="npc", id=256418, name="Krom'rosh"}, note="Krom'rosh: Clugfist's Decree", tip="Back to Rog'mar: from Bolder'ok south-west down the river, or from the port, where your Hearthstone is set. Krom'rosh in the middle of the fort: Clugfist's word sends him looking for Da'grosh, his warrior in the west.", onQuest={95428}, section="Riverglades (41-44)", zoneName="Riverglades", p=1337, place="Rog'mar", was=3417}, -- 3561
  {t="A", q=94744, name="The Wayward Warrior", foreverOnly=true, z=16591, x=59.37, y=45.6, target={kind="npc", id=256418, name="Krom'rosh"}, note="The Wayward Warrior: for Da'grosh, west of Sunnyglade", onQuest={95428}, section="Riverglades (41-44)", zoneName="Riverglades", p=1337, place="Rog'mar", was=3418}, -- 3562
  {t="T", q=95882, name="WANTED: Scoutmaster Vargas", foreverOnly=true, z=16591, x=60.46, y=47.86, target={kind="npc", id=258031, name="Neza Bloodsnout"}, onQuest={95882}, section="Riverglades (41-44)", zoneName="Riverglades", p=1338, place="Neza Bloodsnout", was=3419}, -- 3563
  {t="F", text="Kargath", tip="The rest of this guide is Da'grosh's camp in the west, which waits on Chogg'Zac: without him the Riverglades end here. Back to Rog'mar from the port, where your Hearthstone is set: Grakna, the wind rider master in the middle of the fort, flies to Kargath in the Badlands, where the next guide starts.", notTurnedIn={94744}, notOnQuest={94744}, taxi="Kargath", section="Riverglades (41-44)", p=1339, place="Fly to Kargath"}, -- 3564
  {t="T", q=94744, name="The Wayward Warrior", foreverOnly=true, z=16591, x=33.47, y=37.93, target={kind="npc", id=258570, name="Da'grosh"}, note="Da'grosh", tip="West from Rog'mar through Sunnyglade and on up the valley towards Twilight's Shroud: Da'grosh, Krom'rosh's wayward warrior, keeps a camp in the hills below the Twilight cult's fortress.", onQuest={94744}, section="Riverglades (41-44)", zoneName="Riverglades", p=1340, place="Da'grosh", was=3420}, -- 3565
  {t="A", q=95431, name="Rumblings of Discontent", foreverOnly=true, z=16591, x=33.47, y=37.93, target={kind="npc", id=258570, name="Da'grosh"}, note="Rumblings of Discontent", onQuest={94744}, section="Riverglades (41-44)", zoneName="Riverglades", p=1340, place="Da'grosh", was=3421}, -- 3566
  {t="A", q=94745, name="Carving a Path", foreverOnly=true, z=16591, x=33.47, y=37.93, target={kind="npc", id=258570, name="Da'grosh"}, note="Carving a Path", onQuest={94744}, section="Riverglades (41-44)", zoneName="Riverglades", p=1340, place="Da'grosh", was=3422}, -- 3567
