  {t="T", q=95431, name="Rumblings of Discontent", foreverOnly=true, z=16591, x=27.66, y=36.54, target={kind="npc", id=260993, name="Crag'rog"}, note="Crag'rog", tip="Crag'rog, a Bolder'ok ogre, hides in the cave west of Da'grosh's camp.", onQuest={95431}, section="Riverglades (41-44)", zoneName="Riverglades", p=1341, place="Crag'rog", was=3424}, -- 3569
  {t="A", q=95432, name="Rise Up!", foreverOnly=true, z=16591, x=27.66, y=36.54, target={kind="npc", id=260993, name="Crag'rog"}, note="Rise Up!", onQuest={95431}, section="Riverglades (41-44)", zoneName="Riverglades", p=1341, place="Crag'rog", was=3425}, -- 3570
  {t="C", q=94745, obj=1, name="Carving a Path", foreverOnly=true, z=16591, x=27.45, y=36.3, note="Twilight Fanatic", tip="The cult's camps fill the valley south and west of Da'grosh. Twilight Champions drop the Twilight Key that frees a captive Rog'mar Scout: free them as you find them. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. Overlord Kilgar and Executioner Morg (elites, 46) hold the fortress at the valley's head: pull the cultists away from them. Sergeant Riftan's Alliance camp sits at the valley's south end, and its Farholde Lookouts (level 46) attack the Horde: stay north of it.", onQuest={94745, 94748}, section="Riverglades (41-44)", zoneName="Riverglades", p=1342, place="The Twilight camps", was=3426}, -- 3571
  {t="C", q=94745, obj=2, name="Carving a Path", foreverOnly=true, z=16591, x=27.37, y=36.17, note="Twilight Corrupter", onQuest={94745, 94748}, section="Riverglades (41-44)", zoneName="Riverglades", p=1342, place="The Twilight camps", was=3427}, -- 3572
  {t="C", q=94745, obj=3, name="Carving a Path", foreverOnly=true, z=16591, x=27.63, y=36.45, note="Twilight Champion", onQuest={94745, 94748}, section="Riverglades (41-44)", zoneName="Riverglades", p=1342, place="The Twilight camps", was=3428}, -- 3573
  {t="C", q=94748, name="Break Their Chains", foreverOnly=true, z=16591, x=29.4, y=40.5, note="free five captive Rog'mar Scouts", onQuest={94745, 94748}, section="Riverglades (41-44)", zoneName="Riverglades", p=1342, place="The Twilight camps", was=3429}, -- 3574
  {t="C", q=95432, name="Rise Up!", foreverOnly=true, z=16591, x=26.9, y=34.9, note="recruit five Ogre Miners", tip="Careful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in.", onQuest={95432}, section="Riverglades (41-44)", zoneName="Riverglades", p=1343, place="The ogre mine", was=3430}, -- 3575
  {t="T", q=95432, name="Rise Up!", foreverOnly=true, z=16591, x=27.66, y=36.54, target={kind="npc", id=260993, name="Crag'rog"}, onQuest={95432}, section="Riverglades (41-44)", zoneName="Riverglades", p=1344, place="Crag'rog", was=3431}, -- 3576
  {t="T", q=94745, name="Carving a Path", foreverOnly=true, z=16591, x=33.47, y=37.93, target={kind="npc", id=258570, name="Da'grosh"}, onQuest={94745, 94748}, section="Riverglades (41-44)", zoneName="Riverglades", p=1345, place="Da'grosh", was=3432}, -- 3577
