  {t="A", q=94768, name="Bring Me His Head", group=true, foreverOnly=true, z=16591, x=33.47, y=37.93, target={kind="npc", id=258570, name="Da'grosh"}, note="Da'grosh", tip="Overlord Kilgar is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised.", turnedIn={94745}, section="Riverglades (41-44)", zoneName="Riverglades", p=1346, place="Bring Me His Head", was=3434}, -- 3579
  {t="C", q=94768, obj=1, name="Bring Me His Head", group=true, foreverOnly=true, z=16591, x=26.1, y=43.9, note="Kilgar's Head", turnedIn={94745}, section="Riverglades (41-44)", zoneName="Riverglades", p=1346, place="Bring Me His Head", was=3435}, -- 3580
  {t="T", q=94768, name="Bring Me His Head", group=true, foreverOnly=true, z=16591, x=33.47, y=37.93, target={kind="npc", id=258570, name="Da'grosh"}, turnedIn={94745}, section="Riverglades (41-44)", zoneName="Riverglades", p=1346, place="Bring Me His Head", was=3436}, -- 3581
  {t="G", text="Twilight's Shroud", z=16591, x=32.0, y=29.9, tip="The next guide flies from Kargath in the Badlands: up through Twilight's Shroud, the pass at the valley's north-west end, just north of Da'grosh's camp. Coming from Rog'mar, ride west through Sunnyglade and keep north of the Twilight camps below the pass.", notInZone="Badlands", section="Riverglades (41-44)", zoneName="Riverglades", p=1347, place="Twilight's Shroud"}, -- 3582
  {t="G", text="Badlands", tip="Across the Badlands to Kargath, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress.", section="Riverglades (41-44)", p=1348, place="Kargath"}, -- 3583
  {t="FP", text="Kargath flight path", section="Riverglades (41-44)", p=1348, place="Kargath"}, -- 3584
  {t="G", text="Kargath flight master", z=33, x=4.1, y=44.9, tip="Coming from the Riverglades: Kargath's flight master stands at the foot of the fortress.", inZone="Badlands", section="Feralas & Tanaris (44-47)", zoneName="Stranglethorn Vale", p=1349, place="Fly to Grom'gol"}, -- 3585
  {t="F", text="Grom'gol", inZone="Badlands", section="Feralas & Tanaris (44-47)", p=1349, place="Fly to Grom'gol"}, -- 3586
  {t="G", text="Stonard flight master", z=33, x=46.1, y=54.7, inZone="Swamp of Sorrows", section="Feralas & Tanaris (44-47)", zoneName="Stranglethorn Vale", p=1350, place="Fly to Grom'gol"}, -- 3587
  {t="F", text="Grom'gol", inZone="Swamp of Sorrows", section="Feralas & Tanaris (44-47)", p=1350, place="Fly to Grom'gol"}, -- 3588
  {t="A", q=586, name="Speaking with Gan'zulah", z=33, x=32.22, y=27.6, target={kind="object", id=2076, name="Bubbling Cauldron"}, note="the Bubbling Cauldron: Speaking with Gan'zulah", tip="The flight lands at Grom'gol. Stranglethorn's harder errands, carried from your first visit, fit you now: the Skullsplitter chief, Zanzil's camps, Booty Bay's pirates, the naga coast and Mokk, before the Swamp of Sorrows and the Undercity. The Bubbling Cauldron beside Nimboya has the Skullsplitter chief's quest.", section="Feralas & Tanaris (44-47)", zoneName="Stranglethorn Vale", p=1351, place="Grom'gol Base Camp", was=3444}, -- 3589
  {t="C", q=209, obj=1, name="Skullsplitter Tusks", gv="Collect", gw="Skullsplitter Tusk", optional=true, z=33, x=45.56, y=38.64, note="Collect Skullsplitter Tusk", tip="The hunters also drop Kebok's tusks and Kin'weelay's necklaces. Collect any you still need during the cauldron hunt.", lvlMin=44.0, notReady=586, onQuest={209, 598}, section="Feralas & Tanaris (44-47)", zoneName="Stranglethorn Vale", p=1352, place="Tusks and necklaces on the Skullsplitter hunt"}, -- 3590
