  {t="T", q=621, name="Zanzil's Secret", z=33, x=27.12, y=77.21, target={kind="npc", id=2498, name="Crank Fizzlebub"}, note="Crank Fizzlebub, inside", tip="In Booty Bay: Privateer Bloads on the docks, Crank Fizzlebub inside the inn, MacKinley, Kebok and Krazek upstairs.", section="Feralas & Tanaris (44-47)", zoneName="Stranglethorn Vale", p=1364, place="Booty Bay", was=3469}, -- 3628
