  {t="T", q=348, name="Stranglethorn Fever", z=33, x=27.61, y=76.74, target={kind="npc", id=2486, name="Fin Fizracket"}, note="Fin Fizracket, by the inn", ready=348, section="Feralas & Tanaris (44-47)", zoneName="Stranglethorn Vale", p=1365, place="Fin Fizracket", was=3468}, -- 3630
  {t="A", q=580, name="Whiskey Slim's Lost Grog", z=33, x=27.14, y=77.45, target={kind="npc", id=2491, name="Whiskey Slim"}, note="Whiskey Slim, in the inn: his bottles wash up on the Hinterlands coast, around level 48", tip="Under 40 on your first Booty Bay visit? Whiskey Slim, in the inn, and \"Sea Wolf\" MacKinley, on the top floor, have their quests for you now.", notTurnedIn={348}, notOnQuest={348}, section="Feralas & Tanaris (44-47)", zoneName="Stranglethorn Vale", p=1366, place="Whiskey Slim and Fin Fizracket"}, -- 3631
  {t="A", q=2872, name="Stoley's Debt", z=33, x=27.78, y=77.07, target={kind="npc", id=2501, name="\"Sea Wolf\" MacKinley"}, note="MacKinley, on the top floor: Stoley's Debt, for Stoley in Tanaris on this guide", notTurnedIn={348}, notOnQuest={348}, section="Feralas & Tanaris (44-47)", zoneName="Stranglethorn Vale", p=1366, place="Whiskey Slim and Fin Fizracket"}, -- 3632
  {t="A", q=348, name="Stranglethorn Fever", group=true, z=33, x=27.61, y=76.74, target={kind="npc", id=2486, name="Fin Fizracket"}, note="Fin Fizracket, beside the inn: Stranglethorn Fever", tip="Group quest: Stranglethorn Fever ends at Witch Doctor Unbagwa in Mistvale. Hand him ten gorilla fangs and he calls three waves of gorillas (41-42), one after another, then Mokk the Savage (44). In players' recordings, 12 of the 27 people who started it died there. Take it if you have a friend or two along.", notTurnedIn={348}, notOnQuest={348}, section="Feralas & Tanaris (44-47)", zoneName="Stranglethorn Vale", p=1367, place="Fin Fizracket"}, -- 3633
  {t="N", text="Collect Gorilla Fang", group=true, note="Gorilla Fang", tip="North into Mistvale, a short ride from Booty Bay: Witch Doctor Unbagwa sits among the gorillas. Hand him ten gorilla fangs and stay by him: three waves of gorillas, then Mokk the Savage. Start at full health and mana.", notReady=348, onQuest={348}, section="Feralas & Tanaris (44-47)", p=1368, place="Witch Doctor Unbagwa"}, -- 3634
