  {t="T", q=649, name="Ripple Recovery", z=1637, x=59.65, y=36.94, target={kind="npc", id=6987, name="Malton Droffers"}, note="Malton Droffers", section="Dustwallow Marsh (47-47)", zoneName="Orgrimmar", p=1477, place="Orgrimmar", was=3683}, -- 3925
