  {t="C", q=1172, obj=1, name="The Brood of Onyxia", gv="Click", gw="Egg of Onyxia", z=15, x=48.47, y=73.59, note="Click the Egg of Onyxia", tip="The Eggs of Onyxia lie in the dragon caves in the Wyrmbog's south-east, guarded by the scalebanes; smash five.", section="Dustwallow Marsh (47-47)", zoneName="Dustwallow Marsh", p=1491, place="Onyxia's eggs", was=3764}, -- 3965
  {t="C", q=1261, obj=1, name="Marg Speaks", z=15, x=54.2, y=64.0, note="Jeweled Pendant", tip="On the way back north from the dragon caves, the Muckshell Razorclaws and Pincers (41-44) crowd the shallows just north of the caves; about one in twenty carries the Jeweled Pendant Marg Speaks asks for.", onQuest={1261}, section="Dustwallow Marsh (47-47)", zoneName="Dustwallow Marsh", p=1492, place="Muckshell crabs"}, -- 3966
  {t="G", text="Firemane Scout", z=15, x=37.5, y=68.3, tip="Overlord Mok'Morokk's challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the Wyrmbog's northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the Zul'Farrak dungeon instead.", lvlBelow=45.37, solo=1173, section="Dustwallow Marsh (47-47)", zoneName="Dustwallow Marsh", p=1493, place="Level 45.37"}, -- 3967
  {t="N", text="Reach level 45.37", note="grind on Firemane Scout", lvlBelow=45.37, solo=1173, section="Dustwallow Marsh (47-47)", p=1493, place="Level 45.37"}, -- 3968
