  {t="A", q=1262, name="Report to Zor", z=15, x=35.21, y=30.66, target={kind="npc", id=4791, name="Nazeer Bloodpike"}, note="for Zor Lonetree in Orgrimmar, on the Azshara guide's Orgrimmar stop", section="Dustwallow Marsh (47-47)", zoneName="Dustwallow Marsh", p=1494, place="Brackenwall Village"}, -- 3971
  {t="N", text="Keep Natural Materials and Improved Quality: Feralas' sprites, hippogryphs, Zorbin's coast and the Rage Scar yetis come on your Feralas loop at about 51, with the Muisek chain.", section="Dustwallow Marsh (47-47)", p=1494, place="Brackenwall Village"}, -- 3972
  {t="A", q=1173, name="Challenge Overlord Mok'Morokk", group=true, z=15, x=36.29, y=31.41, target={kind="npc", id=4500, name="Overlord Mok'Morokk"}, note="Overlord Mok'Morokk", tip="Overlord Mok'Morokk is elite: grouping up is advised. Beat him down until he gives up, then report to Draz'Zilb.", section="Dustwallow Marsh (47-47)", zoneName="Dustwallow Marsh", p=1495, place="Challenge Overlord Mok'Morokk", was=3768}, -- 3973
