  {t="A", q=992, name="Gadgetzan Water Survey", z=440, x=50.21, y=27.48, target={kind="npc", id=7724, name="Senior Surveyor Fizzledowser"}, note="Senior Surveyor Fizzledowser", tip="You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.", notTurnedIn={992}, notOnQuest={992}, section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1499, place="Senior Surveyor Fizzledowser", was=3800}, -- 3986
  {t="G", text="Sandsorrow Watch", z=440, x=39.0, y=29.0, section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1500, place="Tanaris"}, -- 3987
  {t="C", q=992, obj=1, name="Gadgetzan Water Survey", gv="Use", gw="Untapped Dowsing Widget", z=440, x=39.0, y=29.2, note="Use the Untapped Dowsing Widget; Collect Tapped Dowsing Widget", tip="West of Gadgetzan, use the Untapped Dowsing Widget beside the water hole in the troll camp.", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1501, place="Sandsorrow Watch", was=3802}, -- 3988
  {t="T", q=992, name="Gadgetzan Water Survey", z=440, x=50.21, y=27.48, target={kind="npc", id=7724, name="Senior Surveyor Fizzledowser"}, note="Senior Surveyor Fizzledowser", tip="Back east to Fizzledowser on the west side of Gadgetzan; Marvon is south from there.", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1502, place="Senior Surveyor Fizzledowser", was=3803}, -- 3989
  {t="A", q=82, name="Noxious Lair Investigation", z=440, x=50.21, y=27.48, target={kind="npc", id=7724, name="Senior Surveyor Fizzledowser"}, section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1502, place="Senior Surveyor Fizzledowser", was=3804}, -- 3990
  {t="A", q=3161, name="Gahz'ridian", z=440, x=52.71, y=45.92, target={kind="npc", id=7771, name="Marvon Rivetseeker"}, tip="West along the road south; Marvon camps by the ruins at the Broken Pillar. Put on his Gahz'ridian Detector: it shows the buried ornaments, here and around the Dunemaul Compound.", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1503, place="Marvon Rivetseeker", was=3805}, -- 3991
  {t="C", q=3161, obj=1, name="Gahz'ridian", gv="Collect", gw="Gahz'ridian Ornament", z=440, x=52.3, y=45.3, note="Collect Gahz'ridian Ornament", tip="Dig up the Gahz'ridian ornaments around the Broken Pillar and north of the Dunemaul Compound.", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1504, place="Gahz'ridian ornaments", was=3806}, -- 3992
  {t="C", q=82, obj=1, name="Noxious Lair Investigation", gv="Collect", gw="Centipaar Insect Parts", z=440, x=36.26, y=45.05, note="Collect Centipaar Insect Parts", tip="Careful: Centipaar Swarmers cast Silithid Swarm both in and out of combat, which brings small adds that interrupt you. The Sandreavers are 49-50: take the Workers and Tunnelers.", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1505, place="The Noxious Lair", was=3807}, -- 3993
  {t="C", q=5863, obj=1, name="The Dunemaul Compound", gv="Kill", gw="Dunemaul Brute", z=440, x=38.91, y=51.3, note="Kill Dunemaul Brute", tip="Careful: Gor'marok is one to two levels above you here, and the Ogre Mages and Warlocks (46-48) cast from range: pull from the compound's edge, one at a time, and leave Gor'marok for last with full health.", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1506, place="The Dunemaul Compound", was=4122}, -- 3994
  {t="C", q=5863, obj=2, name="The Dunemaul Compound", gv="Kill", gw="Dunemaul Enforcer", z=440, x=38.86, y=51.95, note="Kill Dunemaul Enforcer", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1506, place="The Dunemaul Compound", was=4123}, -- 3995
  {t="C", q=5863, obj=3, name="The Dunemaul Compound", z=440, x=41.5, y=57.8, note="Below ground", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1506, place="The Dunemaul Compound", was=4124}, -- 3996
  {t="N", text="Collect OOX-17/TN Distress Beacon", optional=true, note="OOX-17/TN Distress Beacon, a rare drop", tip="Careful: The other thistleshrub mobs in the area are level 48-50 and wander a lot, so you can easily pull extra mobs: take the Dew Collectors at the valley's edge, and leave Tran'rek's Gnarled Thistleshrubs and Rootshapers (49-50) for the Broken Pillar ride into Un'Goro at about 51.", section="Tanaris & Searing Gorge (47-49)", p=1507, place="Thistleshrub Valley: kill these as you meet them"}, -- 3997
  {t="C", q=2605, obj=1, name="The Thirsty Goblin", gv="Collect", gw="Laden Dew Gland", z=440, x=29.2, y=66.1, note="Collect Laden Dew Gland", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1507, place="Thistleshrub Valley: kill these as you meet them", was=3809}, -- 3998
  {t="A", q=1560, name="Tooga's Quest", z=440, x=30.2, y=70.7, target={kind="npc", id=5955, name="Tooga"}, note="Tooga", tip="Tooga waits in the valley. Walk him all the way to his wife Torta in Steamwheedle Port, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. Yeh'kinya stands in the port too.", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1508, place="Tooga's escort", was=3810}, -- 3999
  {t="C", q=1560, name="Tooga's Quest", z=440, x=66.58, y=25.67, section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1508, place="Tooga's escort", was=3811}, -- 4000
  {t="T", q=1560, name="Tooga's Quest", z=440, x=66.58, y=25.67, target={kind="npc", id=6015, name="Torta"}, note="Torta, Steamwheedle Port", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1509, place="Steamwheedle Port", was=3812}, -- 4001
  {t="T", q=3520, name="Screecher Spirits", z=440, x=66.99, y=22.36, target={kind="npc", id=8579, name="Yeh'kinya"}, note="Yeh'kinya", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1509, place="Steamwheedle Port", was=3813}, -- 4002
  {t="C", q=379, obj=1, name="Slake That Thirst", gv="Collect", gw="Wastewander Water Pouch", z=440, x=60.0, y=23.4, note="Collect Wastewander Water Pouch", tip="Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and Shadow Bolt. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less.", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1510, place="Slake That Thirst"}, -- 4003
  {t="T", q=379, name="Slake That Thirst", z=440, x=52.46, y=28.51, target={kind="npc", id=7407, name="Chief Engineer Bilgewhizzle"}, section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1511, place="Gadgetzan"}, -- 4004
  {t="N", text="Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts Tanaris Field Sampling, a two-hour timer, so use it on the way back north from Scrimshank's hive.", section="Tanaris & Searing Gorge (47-49)", p=1511, place="Gadgetzan"}, -- 4005
  {t="T", q=5863, name="The Dunemaul Compound", z=440, x=52.82, y=27.4, target={kind="npc", id=11758, name="Andi Lynn"}, note="Andi Lynn", tip="Andi Lynn stands a few steps from Bilgewhizzle: the Dunemaul Compound.", ready=5863, section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1512, place="Andi Lynn", was=4216}, -- 4006
