  {t="T", q=351, name="Find OOX-17/TN!", optional=true, z=440, x=60.23, y=64.72, target={kind="npc", id=7784, name="Homing Robot OOX-17/TN"}, note="Homing Robot OOX-17/TN", section="Tanaris & Searing Gorge (47-49)", zoneName="Tanaris", p=1516, place="OOX-17/TN", was=3828}, -- 4017
