  {t="T", q=32, name="Rise of the Silithid", z=1637, x=56.26, y=46.68, target={kind="npc", id=7010, name="Zilzibin Drumlore"}, note="Zilzibin Drumlore, the Drag", tip="On the way through Orgrimmar to the flight master, step into the Drag: Zilzibin takes the insect report from Tanaris.", onQuest={32}, section="Azshara, Feralas & Stranglethorn Vale (50-51)", zoneName="Orgrimmar", p=1594, place="Zilzibin Drumlore", was=4040}, -- 4231
  {t="A", q=4494, name="March of the Silithid", z=1637, x=56.26, y=46.68, target={kind="npc", id=7010, name="Zilzibin Drumlore"}, tip="March of the Silithid needs level 50: Zilzibin, in the Drag, gives it from then on. Under 50, it waits: if you reach 50 in Azshara, this guide brings you back for it from Valormok; else the Azshara guide at 55 offers it again.", lvlMin=50.0, available={4494}, section="Azshara, Feralas & Stranglethorn Vale (50-51)", zoneName="Orgrimmar", p=1595, place="Zilzibin Drumlore", was=4058}, -- 4232
