  {t="C", q=3783, name="Are We There, Yeti?", gv="Collect", gw="Thick Yeti Fur", z=618, x=64.05, y=39.83, note="Collect Thick Yeti Fur", tip="The yeti hills start just south-east of Everlook. Every yeti drops fur. Careful: the Ice Thistle Yetis are 55-56: take the 55s one at a time, and leave the Matriarchs and Patriarchs (56-58), whose horns come on a later visit.", section="Winterspring, Felwood & Thunder Bluff (53-54)", zoneName="Winterspring", p=1773, place="Ice Thistle yetis", was=4391}, -- 4666
  {t="C", q=4809, name="Chillwind Horns", gv="Collect", gw="Uncracked Chillwind Horn", z=618, x=61.19, y=41.7, note="Collect Uncracked Chillwind Horn", tip="The chimaeras roam the snowfields south and west of Everlook. Careful: Chillwind Chimaeras are 55-57: take only the 55s, and the Fledgling Chillwinds (53-55) by Lake Kel'Theril, which carry the horns too. Stay clear of Mazthoril's cave: its blue dragonkin are elite.", section="Winterspring, Felwood & Thunder Bluff (53-54)", zoneName="Winterspring", p=1774, place="Chillwind chimaeras", was=4392}, -- 4667
  {t="T", q=3783, name="Are We There, Yeti?", z=618, x=60.88, y=37.62, target={kind="npc", id=10305, name="Umi Rumplesnicker"}, note="Umi Rumplesnicker", section="Winterspring, Felwood & Thunder Bluff (53-54)", zoneName="Winterspring", p=1775, place="Everlook", was=4393}, -- 4668
  {t="A", q=977, name="Are We There, Yeti?", z=618, x=60.88, y=37.62, target={kind="npc", id=10305, name="Umi Rumplesnicker"}, note="Umi: keep it, the Pristine Yeti Horns come on the Eastern Plaguelands guide's Everlook stop at about 56", section="Winterspring, Felwood & Thunder Bluff (53-54)", zoneName="Winterspring", p=1775, place="Everlook", was=4394}, -- 4669
  {t="T", q=4809, name="Chillwind Horns", z=618, x=61.63, y=38.61, target={kind="npc", id=10468, name="Felnok Steelspring"}, note="Felnok Steelspring", section="Winterspring, Felwood & Thunder Bluff (53-54)", zoneName="Winterspring", p=1775, place="Everlook", was=4395}, -- 4670
  {t="N", text="The Matriarchs and Patriarchs that carry Umi's horns are 56-58: leave them for that later stop.", section="Winterspring, Felwood & Thunder Bluff (53-54)", p=1775, place="Everlook"}, -- 4671
