  {t="FP", text="Moonglade flight path", z=493, x=32.09, y=66.61, note="Faustron", tip="South to Moonglade's flight master (the Alliance's at the southern end of the valley, the Horde's at its south-western end) and fly to Everlook for Kaylaena's parts order.", section="Mount Hyjal (56-58)", zoneName="Moonglade", p=1967, place="Fly to Everlook"}, -- 5111
  {t="F", text="Everlook", section="Mount Hyjal (56-58)", p=1967, place="Fly to Everlook"}, -- 5112
  {t="T", q=92008, name="Premiere Parts", foreverOnly=true, z=618, x=61.33, y=36.92, target={kind="npc", id=228216, name="Nami"}, note="Nami", tip="Nami stands between Everlook's two flight masters. Her crate holds fragile cells that fizzle out in time and when knocked about: fly straight back to the Tainted Foothills and take it to Kaylaena without detours or fights (about four minutes in the recording). If it fizzles out anyway, Nami fills it again.", section="Mount Hyjal (56-58)", zoneName="Winterspring", p=1968, place="Nami"}, -- 5113
  {t="A", q=92009, name="Crate Expectations", foreverOnly=true, z=618, x=61.33, y=36.92, target={kind="npc", id=228216, name="Nami"}, note="Crate Expectations", section="Mount Hyjal (56-58)", zoneName="Winterspring", p=1968, place="Nami"}, -- 5114
