  {t="C", q=93826, obj=1, name="Deal Dread to Deadwood", foreverOnly=true, z=616, x=33.1, y=69.82, note="Deadwood Totemic", tip="South-west back towards Barkskin Burrow: the Deadwood camps on the slopes east of the burrow hold the Totemics and Fel-Tenders. An elite named Head Scratcher (level 60) may roam the camps' eastern end.", section="Mount Hyjal (56-58)", zoneName="Mount Hyjal", p=2015, place="The Deadwood camps"}, -- 5227
  {t="C", q=93826, obj=2, name="Deal Dread to Deadwood", foreverOnly=true, z=616, x=33.23, y=68.49, note="Deadwood Fel-Tender", section="Mount Hyjal (56-58)", zoneName="Mount Hyjal", p=2015, place="The Deadwood camps"}, -- 5228
