  {t="A", q=92960, name="Siphoned Ephemeral Essence", foreverOnly=true, z=616, x=43.77, y=32.24, target={kind="npc", id=263406, name="Elaena Moonwhisper"}, note="Elaena Moonwhisper: Siphoned Ephemeral Essence", tip="Into Dae'gun, north of the Cradle: the ruins of a Horde base, now held by demons. Elaena Moonwhisper and Witherbeard camp at its western edge; Yashiro, a blademaster, waits a little east of them. Doomguards (elites, levels 58-59) walk among the demons: pull carefully.", section="Mount Hyjal (56-58)", zoneName="Mount Hyjal", p=2020, place="Elaena, Witherbeard and Yashiro"}, -- 5235
  {t="A", q=95793, name="Stemming the Demon Tide", foreverOnly=true, z=616, x=43.74, y=31.94, target={kind="npc", id=249052, name="Witherbeard"}, note="Witherbeard: Stemming the Demon Tide", section="Mount Hyjal (56-58)", zoneName="Mount Hyjal", p=2020, place="Elaena, Witherbeard and Yashiro"}, -- 5236
