  {t="A", q=97009, name="Maerion's Misery", foreverOnly=true, z=616, x=63.2, y=25.8, target={kind="npc", id=267097, name="Maerion Thaelemaches"}, note="Maerion Thaelemaches: Maerion's Misery", tip="Careful: Legion Hulks (60, rare elites) stomp through Dae'gun's camps, and Doomguard Xarkul, an elite (level 61), walks this corner: give them room.", section="Mount Hyjal (56-58)", zoneName="Mount Hyjal", p=2021, place="Maerion Thaelemaches"}, -- 5238
