  {t="A", q=96003, name="Drawing Down the Malevolent", group=true, foreverOnly=true, z=616, x=43.77, y=32.24, target={kind="npc", id=263406, name="Elaena Moonwhisper"}, note="Elaena Moonwhisper", tip="A group choice: Bethra'zel and Mazzogore are level 60 elites until Elaena's eye drains them. Drain each one first, then fight it; players in our recordings killed both once drained. Grouping up is advised.", section="Mount Hyjal (56-58)", zoneName="Mount Hyjal", p=2025, place="Drawing Down the Malevolent"}, -- 5258
