  {t="A", q=93197, name="Mending Communications", foreverOnly=true, z=616, x=70.87, y=51.55, target={kind="npc", id=243815, name="Sebelia"}, note="Sebelia: Mending Communications: for Innkeeper Vizzie in Everlook, at the end", section="Mount Hyjal (56-58)", zoneName="Mount Hyjal", p=2031, place="The Summit of Eternity"}, -- 5268
