  {t="T", q=96025, name="As the Crow Flies", foreverOnly=true, z=616, x=68.99, y=49.99, target={kind="npc", id=254915, name="Thisalee Crow"}, tip="Thisalee Crow, at the Summit, for Elaena's message.", onQuest={96025}, section="Mount Hyjal (56-58)", zoneName="Mount Hyjal", p=2032, place="As the Crow Flies"}, -- 5270
