  {t="A", q=92533, name="Twisted Tools", group=true, foreverOnly=true, z=616, x=68.88, y=48.35, target={kind="npc", id=243855, name="Toron Rockhoof"}, note="Toron Rockhoof: Twisted Tools", section="Mount Hyjal (56-58)", zoneName="Mount Hyjal", p=2033, place="The Summit's Blackthorne quests"}, -- 5272
