  {t="T", q=980, name="The New Springs", z=618, x=31.27, y=45.16, target={kind="npc", id=9298, name="Donova Snowden"}, note="From Krakle in Un'Goro, if you didn't bring it to her earlier", tip="Back into the Timbermaw tunnel and take the Winterspring exit; Donova camps by the hot springs just outside.", section="Felwood, Moonglade & Winterspring (59-60)", zoneName="Winterspring", p=2137, place="Donova Snowden"}, -- 5473
